const e={id:"s06",unidad:1,semana:6,kind:"aprendizaje",temaGenerador:"Una refacción nutritiva con recursos locales",title:"Una refacción nutritiva con recursos locales",subtitle:"Nutrientes, opciones disponibles, conjuntos, comunicación, proyecto y costo",icon:"Salad",color:"var(--area-cnt)",contexto:"Las refacciones posibles cambian según la comunidad, la temporada, la disponibilidad y el presupuesto. Compararemos opciones que podrían encontrarse en distintos lugares de Guatemala, como tortilla, frijol, pepitoria, huevo, banano, papaya, naranja, güisquil o aguacate, sin asumir que todas están disponibles para todas las familias. Analizaremos qué nutrientes pueden aportar, compararemos conjuntos y prepararemos una propuesta con presupuesto. Antes de elegir o preparar alimentos se consultan alergias, intolerancias, restricciones alimentarias y prácticas familiares o culturales. La preparación real requiere higiene y apoyo o supervisión de una persona adulta cuando haya calor, cuchillos, cocción u otros riesgos.",ejes:["vida-familiar","equidad","trabajo","seguridad"],media:{id:"s06-portada",kind:"image",title:"Opciones locales para una refacción",aspect:"16:9",alt:"Mesa escolar con tortillas, frijoles cocidos, bananos, papaya, pepitoria, huevos, güisquil y agua; estudiantes comparan nutrientes y costos.",brief:'Ilustración editorial clara de una mesa escolar en Guatemala. Mostrar porciones separadas de tortilla, frijol cocido, banano, papaya, pepitoria, huevo cocido, güisquil y agua, tarjetas de ingredientes, una tabla de presupuesto y dos conjuntos. Incluir una ficha visible: "consultar alergias y restricciones". Presentar diversidad regional sin afirmar disponibilidad universal. Sin marcas ni juicios morales sobre los alimentos. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo.'},badge:{id:"planificador-refaccion-local",name:"Planificador de opciones locales",icon:"ClipboardCheck",desc:"Comparaste opciones y justificaste un menú, un presupuesto y un plan adaptable."},bank:[{fase:"comprobar",areas:["mat"],cnb:["mat:3.2.3"],prompt:"R = {cacao, canela, clavo} y S = {canela, vainilla}. ¿Cuántos elementos tiene R Δ S?",type:"number-input",props:{answer:3,unit:"elementos"},id:"s06-banco-1"},{fase:"comprobar",areas:["l1"],cnb:["l1:8.2.1"],prompt:"¿Cuál objetivo comunica con precisión un proyecto escolar?",type:"choice",props:{options:[{id:"a",text:"Comparar tres opciones y presentar sus costos el viernes"},{id:"b",text:"El proyecto más bonito"},{id:"c",text:"Que todo salga bien"}],correct:["a"]},id:"s06-banco-2"},{fase:"comprobar",areas:["cnt"],cnb:["cnt:6.1.1"],prompt:"En la parcela X, una pila rota derrama líquido sobre la tierra; en la parcela Y, las pilas usadas están cerradas en un recipiente para entrega autorizada. ¿Qué conclusión se limita a la evidencia?",type:"choice",props:{options:[{id:"a",text:"X muestra una fuente que puede contaminar el suelo; Y reduce esa exposición, pero hace falta revisar otras condiciones"},{id:"b",text:"El color de la tierra prueba qué sustancia contiene"},{id:"c",text:"Guardar las pilas demuestra que todo el entorno está libre de contaminación"}],correct:["a"]},id:"s06-banco-3"},{fase:"comprobar",areas:["ccss"],cnb:["ccss:6.6.6"],prompt:"¿Qué dato permite reconocer cooperación entre países de un bloque americano?",type:"choice",props:{options:[{id:"a",text:"Usan un instrumento regional para coordinar información y acciones sobre una preocupación compartida"},{id:"b",text:"Sus nombres aparecen juntos en una lista"},{id:"c",text:"Pertenecen al mismo hemisferio"}],correct:["a"]},id:"s06-banco-4"},{fase:"comprobar",areas:["l2"],cnb:["l2:4.1.1"],prompt:"Completa según el contexto: “El vehículo que lleva la carga es un ___”.",type:"fill-blank",props:{text:"El vehículo que lleva la carga es un [[carro]].",distractors:["caro","coro"]},id:"s06-banco-5"},{fase:"comprobar",areas:["l3"],cnb:["l3:3.3.1"],prompt:"Complete the mini-sequence with the only connector that closes it: “First, wash the cup. Then, add the fruit. ______, serve it with a clean spoon.”",type:"fill-blank",props:{text:"First, wash the cup. Then, add the fruit. [[Finally]], serve it with a clean spoon.",distractors:["First","Never"]},id:"s06-banco-6"},{fase:"comprobar",areas:["fc"],cnb:["fc:4.2.1"],prompt:"Recibes una imagen humillante de una compañera. ¿Qué acción de testigo es responsable?",type:"choice",props:{options:[{id:"a",text:"No reenviarla, guardar evidencia sin difundirla y pedir apoyo adulto"},{id:"b",text:"Reenviarla solo al grupo cercano"},{id:"c",text:"Responder con otra burla"}],correct:["a"]},id:"s06-banco-7"},{fase:"comprobar",areas:["art"],cnb:["art:3.2.4"],prompt:"Ordena una trama de la apariencia más clara a la más oscura.",type:"order",props:{items:[{id:"a",text:"Cinco puntos muy separados"},{id:"b",text:"Diez puntos a distancia media"},{id:"c",text:"Veinte puntos muy cercanos"}]},id:"s06-banco-8"},{fase:"comprobar",areas:["ef"],cnb:["ef:3.1.2"],prompt:"Después de actividad moderada, ¿qué secuencia favorece una recuperación gradual?",type:"choice",props:{options:[{id:"a",text:"Caminar despacio y alargar suavemente la exhalación"},{id:"b",text:"Detenerse de golpe y contener la respiración"},{id:"c",text:"Acelerar sin observar cómo se siente el cuerpo"}],correct:["a"]},id:"s06-banco-9"},{fase:"comprobar",areas:["pyd"],cnb:["pyd:4.3.1"],prompt:"Ordena la preparación de una propuesta para feria.",type:"order",props:{items:[{id:"a",text:"Definir el objetivo"},{id:"b",text:"Asignar actividades y responsables"},{id:"c",text:"Calcular los recursos"},{id:"d",text:"Presentar y recoger comentarios"}]},id:"s06-banco-10"}]},a=JSON.parse('[{"missionId":"s06","version":"cnb-sexto-f563cc280dc9548b","lesson":{"id":"s06-cnt-1","title":"Hábitos nutricionales que podemos practicar","icon":"Salad","minutes":14,"gancho":"¿Cómo se evalúa una refacción sin llamar “buena” o “mala” a la comida ni a quien la elige?","objetivos":["Evaluar hábitos nutricionales cotidianos con criterios adaptables"],"resumen":["Un hábito nutricional es una práctica repetida relacionada con alimentos y bebidas.","Variedad, agua segura, higiene, regularidad y restricciones personales son criterios para comparar prácticas.","Una decisión posible depende de cultura, disponibilidad, presupuesto y orientación profesional cuando corresponda."],"media":{"id":"s06-cnt-1-habitos","kind":"diagram","title":"Cinco criterios para una refacción","aspect":"16:9","alt":"Mesa con tortilla, frijol, banano y agua junto a cinco rótulos: variedad, agua segura, higiene, regularidad y restricciones.","brief":"Diagrama horizontal 1600×900. Mostrar alimentos guatemaltecos reconocibles y cinco criterios con iconos descriptivos. Incluir la nota “Las opciones dependen de disponibilidad, cultura, presupuesto y necesidades”. Texto grande, contraste alto, sin marcas ni juicios corporales."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:5.3.1"],"title":"Un hábito es una práctica repetida","prompt":"Los hábitos nutricionales incluyen qué, cuándo y cómo comemos o bebemos.","type":"explain","props":{"icon":"CalendarDays","body":"No se juzga a una persona por una comida. Se comparan **prácticas** con criterios y se elige una mejora posible según los recursos disponibles."},"id":"s06-cnt-1-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:5.3.1"],"title":"Criterios adaptables","prompt":"Evalúa hábitos nutricionales con variedad, agua segura, higiene, regularidad y atención a restricciones.","type":"explain","props":{"icon":"ListChecks","body":"**Variedad** reúne opciones distintas; **agua segura** evita exposiciones; **higiene** reduce contaminación; **regularidad** ayuda a organizar; y las **restricciones** requieren consulta. La decisión cambia según cultura, temporada, disponibilidad y presupuesto."},"id":"s06-cnt-1-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:5.3.1"],"title":"Modelo: comparar una práctica","prompt":"Observa cómo evaluar un hábito nutricional sin prometer resultados de salud.","type":"worked-example","props":{"icon":"ClipboardCheck","problem":"Escenario: Ana toma agua segura y lleva tortilla con frijol; hoy hay banano disponible.","steps":[{"text":"Variedad: puede agregar el banano si lo desea y está disponible."},{"text":"Higiene: manos y recipiente limpios."},{"text":"Restricciones: confirmar alergias o indicaciones personales."},{"text":"Decisión posible: mantener el agua y agregar la fruta, sin atribuirle un resultado médico a una sola comida."}],"answer":"La mejora usa criterios y respeta disponibilidad y necesidades."},"id":"s06-cnt-1-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:5.3.1"],"prompt":"Clasifica prácticas del escenario.","hint":"Busca agua segura, higiene, variedad y respeto a restricciones.","explain":"Una práctica puede mejorarse sin etiquetar a la persona ni prohibir alimentos.","type":"sort","props":{"buckets":[{"id":"apoya","label":"Apoya el hábito","icon":"BadgeCheck","color":"var(--c-ok)"},{"id":"revisar","label":"Conviene revisar","icon":"Search","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Lavarse las manos antes de comer","bucket":"apoya"},{"id":"b","text":"Suponer que una opción es segura para todas las alergias","bucket":"revisar"},{"id":"c","text":"Llevar agua de una fuente confirmada como segura","bucket":"apoya"},{"id":"d","text":"Omitir siempre la comida por falta de planificación","bucket":"revisar"}]},"id":"s06-cnt-1-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:5.3.1"],"prompt":"Relaciona cada criterio con una decisión posible.","hint":"La decisión debe ser realizable y no universal.","explain":"Los criterios orientan; la disponibilidad y las necesidades personales modifican la elección.","type":"match","props":{"pairs":[{"id":"a","left":"Variedad","right":"Combinar opciones disponibles de más de un grupo"},{"id":"b","left":"Higiene","right":"Usar manos y recipiente limpios"},{"id":"c","left":"Restricción","right":"Consultar y elegir una alternativa segura"},{"id":"d","left":"Agua segura","right":"Confirmar la fuente antes de beber"}]},"id":"s06-cnt-1-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:5.3.1"],"prompt":"Caso nuevo: Luis repite la misma refacción, lleva agua segura y mantiene higiene; hay otra opción local disponible. ¿Qué decisión evalúa sus hábitos nutricionales con variedad, agua segura, higiene y disponibilidad?","type":"choice","props":{"options":[{"id":"a","text":"Conservar el agua y la higiene, y considerar alternar la opción disponible"},{"id":"b","text":"Decir que su comida es mala y prohibirla"},{"id":"c","text":"Afirmar que una sola opción garantiza todas sus necesidades"}],"correct":["a"]},"id":"s06-cnt-1-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:5.3.1"],"prompt":"Evalúa un hábito nutricional del caso suministrado y escribe una mejora posible usando dos criterios entre variedad, agua segura, higiene, regularidad y restricciones.","type":"short-answer","props":{"minWords":18,"placeholder":"El hábito... Una mejora posible...","model":"El hábito conserva agua segura e higiene. Una mejora posible es alternar opciones disponibles y confirmar restricciones antes de cambiar.","rubric":["Nombré el hábito","Usé dos criterios","Propuse una decisión adaptable"]},"id":"s06-cnt-1-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:5.3.1"],"prompt":"¿Qué evaluación de hábitos nutricionales usa variedad, agua segura, higiene y una decisión adaptable?","type":"choice","props":{"options":[{"id":"a","text":"Comparar esos criterios y ajustar la práctica según disponibilidad y restricciones"},{"id":"b","text":"Clasificar a la persona por una sola comida"},{"id":"c","text":"Eliminar cualquier alimento que no sea perfecto"}],"correct":["a"]},"id":"s06-cnt-1-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:5.3.1"],"prompt":"Evalúa decisiones sobre hábitos nutricionales con variedad, agua segura, higiene y contexto.","type":"true-false","props":{"statements":[{"text":"Una mejora posible puede conservar prácticas útiles y cambiar solo un aspecto realizable.","answer":true},{"text":"La misma opción debe imponerse aunque cambien cultura, disponibilidad o restricciones.","answer":false}]},"id":"s06-cnt-1-9"},{"fase":"reflexionar","areas":["cnt"],"cnb":["cnt:5.3.1"],"prompt":"Revisa cómo tomaste la decisión.","type":"reflection","props":{"statements":["Comparé prácticas con criterios","Evité juzgar alimentos o personas","Reconocí límites de disponibilidad"],"commitments":["Propondré cambios posibles y respetuosos"]},"id":"s06-cnt-1-10"}],"kind":"materia","area":"cnt","day":1}},{"missionId":"s06","version":"cnb-sexto-4f8ea16550bfe6d2","lesson":{"id":"s06-cnt-2","title":"Ambiente sano y ambiente contaminado","icon":"ShieldCheck","minutes":13,"gancho":"Un lugar puede verse ordenado y aun tener agua, aire o suelo contaminados. ¿Qué evidencia permite distinguirlo?","objetivos":["Diferenciar ambientes sanos y contaminados mediante evidencia observable"],"resumen":["Un ambiente sano reduce exposiciones y maneja de forma segura agua, aire, suelo y residuos.","Un ambiente contaminado contiene agentes o residuos que pueden dañar seres vivos.","Una señal aislada orienta una revisión, pero la clasificación necesita evidencia suficiente."],"media":{"id":"s06-cnt-2-ambientes","kind":"diagram","title":"Dos ambientes para comparar","aspect":"16:9","alt":"Dos patios ficticios: uno con residuos contenidos, aire ventilado y agua protegida; otro con humo, aguas residuales y basura dispersa.","brief":"Diagrama comparativo 1600×900 de dos escenarios ficticios, rotulados A y B. Mostrar fuentes concretas de evidencia en agua, aire, suelo y residuos. Evitar indicar la respuesta solo con color; usar rótulos legibles, patrones y alto contraste."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:6.1.1"],"title":"Distinguir requiere evidencia","prompt":"Un ambiente sano y uno contaminado se diferencian por condiciones del agua, aire, suelo y manejo de residuos.","type":"explain","props":{"icon":"Search","body":"Ambiente **sano**: reduce exposiciones y protege recursos. Ambiente **contaminado**: presenta humo, aguas residuales, sustancias o residuos que pueden afectar seres vivos."},"id":"s06-cnt-2-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:6.1.1"],"title":"Cuatro campos de observación","prompt":"Compara agua, aire, suelo y residuos antes de clasificar.","type":"explain","props":{"icon":"TableProperties","body":"Pregunta: ¿hay una fuente de contaminación?, ¿qué recurso alcanza?, ¿qué evidencia se observa?, ¿qué dato faltaría confirmar? Un olor o color por sí solo no identifica siempre la sustancia."},"id":"s06-cnt-2-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:6.1.1"],"title":"Modelo: evidencia y clasificación","prompt":"Diferencia dos ambientes ficticios.","type":"worked-example","props":{"icon":"GitCompare","problem":"Patio A: agua cubierta y residuos en contenedores. Patio B: humo constante y agua residual descargada al suelo.","steps":[{"text":"A muestra prácticas que reducen exposición."},{"text":"B presenta fuentes observables de contaminación del aire y suelo."},{"text":"No afirmamos qué sustancia contiene el agua sin analizarla."}],"answer":"A reúne señales de ambiente sano; B, evidencia de ambiente contaminado."},"id":"s06-cnt-2-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Clasifica la evidencia suministrada.","hint":"Ubica la condición del recurso, no la apariencia general.","explain":"Manejo seguro apoya un ambiente sano; descargas, humo y residuos dispersos evidencian contaminación.","type":"sort","props":{"buckets":[{"id":"sano","label":"Ambiente sano","icon":"ShieldCheck","color":"var(--c-ok)"},{"id":"cont","label":"Ambiente contaminado","icon":"CloudFog","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Agua almacenada en recipiente limpio y cubierto","bucket":"sano"},{"id":"b","text":"Humo de quema entra al aula","bucket":"cont"},{"id":"c","text":"Residuos separados y contenidos","bucket":"sano"},{"id":"d","text":"Aguas residuales corren sobre el suelo","bucket":"cont"}]},"id":"s06-cnt-2-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Relaciona evidencia y recurso afectado.","hint":"Pregunta dónde se observa la exposición.","explain":"Nombrar el recurso evita clasificaciones vagas.","type":"match","props":{"pairs":[{"id":"a","left":"Quema con humo persistente","right":"Aire contaminado"},{"id":"b","left":"Descarga de aguas residuales","right":"Agua o suelo contaminado"},{"id":"c","left":"Residuos cerrados y retiro organizado","right":"Condición que apoya un ambiente sano"}]},"id":"s06-cnt-2-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Caso nuevo: un patio tiene residuos contenidos, pero recibe humo. ¿Cómo diferencias ambiente sano y contaminado con evidencia de aire y residuos?","type":"choice","props":{"options":[{"id":"a","text":"El manejo de residuos es favorable, pero el humo evidencia contaminación del aire"},{"id":"b","text":"Es totalmente sano porque está ordenado"},{"id":"c","text":"Es contaminado solo porque el suelo es oscuro"}],"correct":["a"]},"id":"s06-cnt-2-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Diferencia los ambientes C y D usando una evidencia de agua, aire, suelo o residuos y un límite de lo que no puede concluirse.","type":"short-answer","props":{"minWords":18,"placeholder":"C muestra... D muestra... No puede concluirse...","model":"C reduce exposición al contener residuos. D muestra contaminación por humo. Sin análisis no puede nombrarse una sustancia específica.","rubric":["Diferencié ambos ambientes","Usé evidencia concreta","Reconocí un límite"]},"id":"s06-cnt-2-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"¿Qué comparación distingue un ambiente sano de uno contaminado mediante evidencia de agua, aire, suelo o residuos?","type":"choice","props":{"options":[{"id":"a","text":"Agua protegida y residuos contenidos reducen exposición; humo y descargas muestran contaminación"},{"id":"b","text":"Un lugar bonito siempre es sano"},{"id":"c","text":"Todo olor demuestra la misma sustancia"}],"correct":["a"]},"id":"s06-cnt-2-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Diferencia ambiente sano y contaminado con evidencia de agua, aire, suelo o residuos.","type":"true-false","props":{"statements":[{"text":"Una descarga de agua residual al suelo es evidencia de contaminación.","answer":true},{"text":"Un rótulo limpio demuestra por sí solo que todo el ambiente es sano.","answer":false}]},"id":"s06-cnt-2-9"},{"fase":"reflexionar","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Revisa tu clasificación.","type":"reflection","props":{"statements":["Usé evidencia observable","Diferencié recurso y apariencia","Evité afirmar una sustancia sin análisis"],"commitments":["Pediré verificación cuando la evidencia no alcance"]},"id":"s06-cnt-2-10"}],"kind":"materia","area":"cnt","day":3}},{"missionId":"s06","version":"cnb-sexto-aa7abf0c6358b996","lesson":{"id":"s06-pyd-1","title":"Presentar, escuchar y mejorar un proyecto","icon":"ClipboardList","minutes":15,"gancho":"En una feria interactiva, una explicación breve y una pregunta útil pueden mejorar un proyecto antes de realizarlo.","objetivos":["Presentar y mejorar un proyecto sencillo mediante retroalimentación en una mini feria"],"resumen":["El plan suministrado reúne objetivo, dos actividades, responsables y un presupuesto pequeño; una fecha queda pendiente para revisarla.","En la mini feria, la persona expositora presenta objetivo, acciones y costo total en 20 segundos.","La persona visitante escucha y formula una pregunta relevante o un comentario basado en un criterio.","La persona expositora registra la retroalimentación y revisa un campo para mejorar el plan."],"media":{"id":"s06-pyd-1-plan","kind":"diagram","title":"Partes de un plan breve","aspect":"4:3","alt":"Diagrama de referencia con objetivo, dos actividades, presupuesto, etiqueta visual, retroalimentación y revisión.","brief":"Diagrama 1200×900 de referencia. Mostrar campos compactos: objetivo, actividad 1 con responsable y fecha, actividad 2 con responsable y fecha, presupuesto de dos rubros, etiqueta visual, retroalimentación y revisión. Añadir una lista de cotejo para una presentación de 20 segundos. No presentarlo como hoja disponible ni mostrar respuestas estudiantiles. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["pyd"],"cnb":["pyd:4.1.1","pyd:4.3.1"],"ambito":"conocer","title":"Plan y protocolo de mini feria","prompt":"Usarás un plan suministrado y una tarjeta de visitante para simular cómo la retroalimentación mejora un proyecto.","type":"explain","props":{"icon":"MessagesSquare","body":"Participar en una feria es presentar, escuchar con respeto y usar la retroalimentación para mejorar.","reveal":[{"icon":"Presentation","front":"Presentar","back":"Explica objetivo, dos acciones y costo total en 20 segundos."},{"icon":"MessageCircleQuestion","front":"Escuchar","back":"La persona visitante hace una pregunta relevante o comenta un criterio: claridad, viabilidad o costo."},{"icon":"NotebookPen","front":"Registrar","back":"Anota una frase breve sin discutir ni descalificar."},{"icon":"RefreshCw","front":"Mejorar","back":"Agradece y revisa un campo del plan cuando el comentario ayuda al proyecto."}]},"id":"s06-pyd-1-1"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:4.1.1","pyd:4.3.1"],"ambito":"hacer","title":"Modelo breve: presentar, escuchar y revisar","prompt":"Observa cómo un proyecto preparado se presenta y mejora durante una mini feria.","type":"worked-example","props":{"icon":"ClipboardCheck","problem":"Proyecto: organizar una caja de intercambio de libros para el grado.","steps":[{"text":"**Plan en una hoja:** objetivo, dos actividades con responsables y fechas, y presupuesto ilustrativo total de Q4."},{"text":"**Presentación de 20 segundos:** “Organizaremos 20 libros. Primero los registramos; después preparamos la caja. El costo total es Q4”."},{"text":"**Visitante:** pregunta con respeto y criterio de viabilidad: “¿Quién revisará que cada libro quede registrado?”"},{"text":"**Presentadora:** responde “Gracias”, registra el comentario y revisa un campo: agrega “comisión de lectura” como responsable de la actividad 1."}],"answer":"La interacción es útil porque la visitante pregunta por un dato del plan y la presentadora usa esa retroalimentación para revisar un campo."},"id":"s06-pyd-1-2"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:4.3.1"],"ambito":"emprender","prompt":"Con ayuda: el plan dice “comprar materiales”, pero no indica cuáles. ¿Qué comentario de visitante ayuda a mejorarlo?","hint":"Un comentario respetuoso se refiere a un criterio del plan y propone precisar, no califica a la persona.","explain":"Pedir que se nombren los materiales usa el criterio de claridad y permite revisar ese campo.","type":"choice","props":{"options":[{"id":"a","text":"¿Podrías nombrar los materiales para que el presupuesto sea claro?"},{"id":"b","text":"Tu proyecto está mal.","feedback":"Descalifica sin señalar un criterio ni una mejora posible."},{"id":"c","text":"Me gusta el color.","feedback":"No ayuda a revisar la claridad o viabilidad del plan."}],"correct":["a"]},"id":"s06-pyd-1-3"},{"id":"s06-pyd-1-4","fase":"construir","areas":["pyd"],"cnb":["pyd:4.1.1"],"ambito":"emprender","title":"Plan suministrado: intercambio de libros","prompt":"Lee este plan ya preparado. No debes copiarlo ni crear otro: lo usarás en la simulación y completarás solamente el dato que la retroalimentación permita mejorar.","type":"explain","props":{"icon":"ClipboardList","body":"**Objetivo:** poner 20 libros en circulación en el grado.\\n\\n**Actividad 1:** registrar los libros. **Responsable:** comisión de lectura. **Fecha:** lunes.\\n\\n**Actividad 2:** preparar la caja de intercambio. **Responsable:** comisión de materiales. **Fecha:** pendiente.\\n\\n**Presupuesto ilustrativo:** etiqueta, Q2; cinta, Q2; caja reutilizada, Q0. **Total:** Q4.\\n\\n**Etiqueta:** pendiente."}},{"id":"s06-pyd-1-5","fase":"aplicar","areas":["pyd"],"cnb":["pyd:4.3.1"],"ambito":"hacer","title":"Etiqueta visual concisa","prompt":"Escribe una **etiqueta visual de 5 a 8 palabras** para identificar el plan suministrado.","type":"short-answer","props":{"minWords":5,"placeholder":"Libros que circulan en nuestro grado","model":"Libros compartidos para aprender juntos","rubric":["Nombra el proyecto con claridad","Tiene entre 5 y 8 palabras"]}},{"id":"s06-pyd-1-6","fase":"aplicar","areas":["pyd"],"cnb":["pyd:4.3.1"],"ambito":"emprender","title":"Mini feria: una interacción y una mejora","prompt":"Realiza una **simulación individual** con el plan y los roles suministrados. La práctica por pareja es una extensión opcional, no requerida.","type":"project","props":{"goal":"Interpretar retroalimentación útil y mejorar un solo campo del plan suministrado.","steps":[{"title":"Presentar","detail":"Lee el objetivo, las dos actividades y el total de Q4 en 20 segundos."},{"title":"Cambiar de rol","detail":"Los roles cambian dentro de la simulación individual. Formula una pregunta suministrada en la voz de la visitante: “La segunda actividad no tiene fecha. ¿Cuándo la realizarás?”"},{"title":"Mejorar un campo","detail":"Registra la retroalimentación “falta fecha” y revisa un campo: agrega “viernes” a la actividad 2."}],"evidence":"Lista de cotejo: la app registra los tres pasos; la nota “falta fecha” y la revisión “viernes” quedan en el cuaderno y no se capturan.","rubric":["Presenté el plan suministrado en 20 segundos","Representé los dos roles suministrados","Registré la frase y agregué una fecha"]}},{"id":"s06-pyd-1-7","fase":"aplicar","areas":["pyd"],"cnb":["pyd:4.3.1"],"ambito":"emprender","prompt":"Transferencia independiente: en otra mini feria, un proyecto tiene actividad y fecha, pero no responsable. ¿Qué revisión mejora ese proyecto?","type":"choice","props":{"options":[{"id":"a","text":"Agregar “comisión de lectura” como responsable"},{"id":"b","text":"Cambiar el color de la etiqueta"},{"id":"c","text":"Aumentar el costo total sin explicación"}],"correct":["a"]}},{"id":"s06-pyd-1-8","fase":"comprobar","areas":["pyd"],"cnb":["pyd:4.3.1"],"prompt":"Boleto de salida: una visitante pregunta quién hará la segunda actividad. ¿Qué acción muestra que la presentación ayudó a mejorar el proyecto?","type":"choice","props":{"options":[{"id":"a","text":"Anotar la pregunta y precisar el responsable en el plan"},{"id":"b","text":"Cambiar el color del título sin revisar el plan"},{"id":"c","text":"Ignorar la pregunta porque la exposición ya terminó"}],"correct":["a"]}},{"id":"s06-pyd-1-9","fase":"comprobar","areas":["pyd"],"cnb":["pyd:4.3.1"],"prompt":"Evalúa la conducta de una persona visitante durante un turno breve.","type":"true-false","props":{"statements":[{"text":"Escucha sin interrumpir hasta que termina la explicación.","answer":true},{"text":"Pregunta por un dato del plan con lenguaje respetuoso.","answer":true},{"text":"Cambia por su cuenta lo escrito en el plan ajeno.","answer":false,"why":"La persona visitante aporta una pregunta o comentario; quien presenta decide y realiza la revisión."}]}},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["pyd"],"cnb":["pyd:4.1.1","pyd:4.3.1"],"type":"reflection","props":{"statements":["Presento un proyecto en 20 segundos","Doy retroalimentación respetuosa basada en un criterio","Mejoro un campo después de escuchar"],"commitments":["Haré preguntas que ayuden a precisar el plan","Registraré la retroalimentación antes de decidir una revisión"]},"id":"s06-pyd-1-10"}],"kind":"materia","area":"pyd","day":3}},{"missionId":"s06","version":"cnb-sexto-d6bdaa15885c9b52","lesson":{"id":"s06-art-2","title":"Texturas con materiales: el cuadro en relieve","icon":"Layers","minutes":15,"gancho":"Una tapita, un puñado de aserrín, un pedazo de tela vieja y una hoja seca. Para muchos es basura; para una artista, son texturas esperando una obra. ¿Qué harías tú con ellos?","objetivos":["Crear texturas táctiles transformando materiales: pegar, arrugar, rasgar, enrollar, estampar y modelar"],"resumen":["Una textura táctil se crea con materiales y técnicas: pegar granos o semillas, arrugar o rasgar papel, enrollar tiras, pegar hilos, estampar con objetos y marcar plastilina o masa de papel con herramientas.","Un mismo material puede dar texturas distintas: el papel liso, arrugado, rasgado o enrollado se siente diferente.","Para un cuadro en relieve: base firme (cartón), un boceto, goma blanca, pocas texturas bien distintas y tiempo de secado.","Reutilizar materiales cuida el ambiente. Trabaja seguro: sin vidrio ni objetos filosos, sin llevarte nada a la boca y lavándote las manos al terminar."],"media":{"id":"s06-art-2-cuadro","kind":"video","title":"Un cuadro que se puede tocar","aspect":"9:16","duration":60,"alt":"Unas manos arman sobre cartón un paisaje de volcán y lago: pegan arena en el volcán, papel arrugado en las nubes, tiras de papel enrollado en el lago, semillas en la orilla y estampan hojas con pintura en el cielo.","brief":"Video vertical de 60 s, plano cenital sobre una mesa cubierta con periódico. Muestra en secuencias cortas: (1) boceto a lápiz de un volcán, un lago y un cielo sobre cartón; (2) goma blanca y arena volcánica espolvoreada en el volcán, se sacude el sobrante; (3) papel de china arrugado para las nubes; (4) tiras de papel enrolladas y pegadas en ondas para el lago; (5) frijoles o semillas en la orilla; (6) estampado con una hoja pintada; (7) plastilina marcada con un tenedor de plástico para una casita. Rótulos: pegar, arrugar, enrollar, estampar, marcar. Cierre: una mano con los ojos tapados recorre el cuadro. Música suave, sin marcas. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["art"],"cnb":["art:3.2.4"],"ambito":"conocer","title":"Seis técnicas para crear texturas","prompt":"Estas técnicas convierten materiales sencillos en texturas. Toca cada una.","type":"explain","props":{"icon":"Layers","body":"Muchas obras de **técnica mixta** combinan varias de ellas. Todas se pueden hacer con materiales reciclados.","reveal":[{"icon":"Droplet","front":"Pegar granos","back":"Unta goma y espolvorea **arena, aserrín, café molido usado o semillas**. Sacude el sobrante cuando seque. Da textura granulosa."},{"icon":"FileText","front":"Arrugar y rasgar","back":"**Arruga** papel de china o periódico para relieves irregulares; **rasga** con los dedos para bordes suaves con pelusa."},{"icon":"RotateCw","front":"Enrollar y trenzar","back":"**Enrolla** tiras de papel o **trenza** lana o hilo y pégalos en líneas u ondas: relieves ordenados."},{"icon":"Stamp","front":"Estampar","back":"Pinta un objeto con relieve (una hoja, una esponja, media papa tallada por un adulto, una tapita) y **presiónalo** sobre el papel."},{"icon":"Hand","front":"Modelar y marcar","back":"Extiende **plastilina, barro o masa de papel** y márcala con un tenedor de plástico, un palito o una concha."},{"icon":"Scissors","front":"Collage de telas","back":"Recorta y pega **retazos** de tela, costal o fieltro: cada tela tiene su propia textura."}]},"id":"s06-art-2-1"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.4"],"ambito":"hacer","title":"Ejemplo resuelto: un volcán que se puede tocar","prompt":"Mira cómo Andrés planifica y hace su **cuadro en relieve** del volcán de su pueblo (como en el video).","type":"worked-example","props":{"icon":"Mountain","problem":"Andrés tiene un cartón, goma blanca, arena, papel de china, periódico, frijoles viejos que ya no sirven para cocinar y plastilina.","steps":[{"text":"**Boceto:** dibuja a lápiz en el cartón el volcán, el cielo, un lago y una casita.","why":"Planificar evita pegar materiales donde no van."},{"text":"**Asigna texturas bien distintas:** volcán = arena (granuloso); nubes = papel de china arrugado (irregular y suave); lago = tiras de periódico enrolladas (ondas ordenadas); orilla = frijoles (bultos duros); casita = plastilina marcada con tenedor.","why":"Como aprendiste en el mapa táctil, texturas distintas se reconocen mejor."},{"text":"**Trabaja de atrás hacia adelante:** primero el cielo y el volcán, después el lago y al final la casita.","why":"Así no aplastas lo que ya pegaste."},{"text":"**Deja secar** acostado toda una noche antes de colgarlo o tocarlo mucho."}],"answer":"Un cuadro con **cinco texturas táctiles** bien distintas, creadas con **cuatro técnicas**: pegar granos (arena en el volcán y frijoles en la orilla), arrugar, enrollar y modelar.","tip":"Usa poca goma en cada zona: si pones mucha, el cartón se moja y se deforma."},"id":"s06-art-2-2"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.4"],"ambito":"conocer","prompt":"Un mismo papel puede sentirse muy distinto. Clasifica cada forma de transformarlo según la textura que crees que da.","explain":"Al **transformar** un material cambias su textura. Arrugar da relieve irregular; enrollar da cilindros ordenados; rasgar deja bordes con pelusa.","type":"sort","props":{"buckets":[{"id":"irr","label":"Relieve irregular","icon":"Mountain","color":"var(--area-art)"},{"id":"ord","label":"Relieve ordenado","icon":"AlignJustify","color":"var(--area-l1)"},{"id":"lis","label":"Liso","icon":"Square","color":"var(--c-ok)"}],"items":[{"id":"x1","text":"Papel arrugado y vuelto a estirar","bucket":"irr"},{"id":"x2","text":"Tiras de papel enrolladas, pegadas en fila","bucket":"ord"},{"id":"x3","text":"Papel pegado plano y sin arrugas","bucket":"lis"},{"id":"x4","text":"Papel doblado en acordeón","bucket":"ord"},{"id":"x5","text":"Bolitas de papel de distintos tamaños","bucket":"irr"}]},"id":"s06-art-2-3"},{"fase":"construir","areas":["art"],"cnb":["art:3.2.4"],"ambito":"hacer","prompt":"Une cada efecto que quieres lograr con la técnica que lo produce.","hint":"Repasa las seis tarjetas de técnicas.","explain":"Cada técnica deja una \\"huella\\" distinta en el material.","type":"match","props":{"leftTitle":"Quiero…","rightTitle":"Técnica","pairs":[{"id":"g","left":"Un suelo granuloso de playa","right":"Pegar arena"},{"id":"n","left":"Nubes con relieve irregular","right":"Arrugar papel de china"},{"id":"h","left":"La huella de las nervaduras de una hoja","right":"Estampar con una hoja pintada"},{"id":"t","left":"Un techo de teja con rayitas","right":"Marcar plastilina con un tenedor"}]},"id":"s06-art-2-4"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.2.4"],"ambito":"hacer","prompt":"Valeria quiere representar un **campo de trigo** en su cuadro, con líneas en relieve que parezcan espigas. ¿Qué técnica le conviene?","explain":"Las tiras enrolladas o la lana trenzada, pegadas en líneas, crean un relieve ordenado parecido a las espigas.","type":"choice","props":{"options":[{"id":"a","text":"Pegar tiras de papel enrolladas o lana trenzada en líneas"},{"id":"b","text":"Pegar papel aluminio liso","feedback":"El aluminio liso no da la sensación de espigas."},{"id":"c","text":"Pintar con un solo color plano","feedback":"Así no se crea una textura táctil."}],"correct":["a"]},"id":"s06-art-2-5"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.2.4"],"ambito":"ser","prompt":"Trabajo seguro y responsable. ¿Verdadero o falso?","explain":"Crear texturas es divertido si cuidas tu cuerpo, el ambiente y a los demás.","type":"true-false","props":{"statements":[{"text":"Puedo usar pedacitos de vidrio para dar brillo a mi cuadro.","answer":false,"why":"El vidrio corta. Usa papel aluminio o papel brillante."},{"text":"Reutilizar cartón, retazos y papel usado cuida el ambiente.","answer":true},{"text":"Si uso semillas, elijo las que ya no sirven para comer.","answer":true},{"text":"Al terminar, me lavo las manos y guardo los materiales.","answer":true}]},"id":"s06-art-2-6"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.2.4"],"ambito":"hacer","prompt":"Planifica tu **cuadro en relieve** sobre un lugar que quieras (tu casa, el mercado, un río, el campo). Escribe: qué lugar es, qué **4 partes** tendrá, qué **textura** y **técnica** usarás en cada parte, y qué **materiales reciclados** usarás.","type":"short-answer","props":{"minWords":40,"placeholder":"Mi cuadro será… La parte 1… con… La parte 2…","model":"Mi cuadro será el mercado de mi pueblo. El suelo será de aserrín pegado, para que se sienta granuloso. El techo de las ventas será de cartón corrugado de una caja vieja, que tiene rayas ordenadas. Los canastos serán de lana trenzada pegada en espiral. Las frutas serán bolitas de plastilina marcadas con un palito. Usaré cartón de caja, lana sobrante y aserrín de la carpintería de mi tío.","rubric":["Nombra el lugar y 4 partes","Asigna una textura distinta a cada parte","Nombra la técnica de cada textura","Usa materiales reciclados y seguros"]},"id":"s06-art-2-7"},{"fase":"aplicar","areas":["art"],"cnb":["art:3.2.4"],"ambito":"hacer","prompt":"**En casa:** realiza el cuadro en relieve que planificaste.","type":"project","props":{"goal":"Crear un cuadro con al menos 4 texturas táctiles hechas con técnicas distintas.","steps":[{"title":"Prepara","detail":"Cubre la mesa con periódico. Reúne cartón, goma blanca y tus materiales reciclados."},{"title":"Boceto","detail":"Dibuja a lápiz las partes de tu cuadro sobre el cartón."},{"title":"Crea texturas","detail":"Trabaja de atrás hacia adelante, con poca goma en cada zona. Usa al menos 4 técnicas."},{"title":"Seca y prueba","detail":"Deja secar una noche. Luego, con los ojos cerrados, recorre tu cuadro: ¿distingues cada parte?"}],"evidence":"Tu cuadro terminado con un título y una lista de las técnicas que usaste.","rubric":["Tiene al menos 4 texturas distintas","Usé técnicas diferentes","Los materiales están firmes y secos","Trabajé con orden y seguridad"]},"id":"s06-art-2-8"},{"fase":"comprobar","areas":["art"],"cnb":["art:3.2.4"],"prompt":"¿Qué técnica consiste en **pintar un objeto con relieve y presionarlo** sobre el papel?","type":"choice","props":{"options":[{"id":"a","text":"Estampar"},{"id":"b","text":"Arrugar"},{"id":"c","text":"Rasgar"},{"id":"d","text":"Frotado"}],"correct":["a"]},"id":"s06-art-2-9"},{"fase":"comprobar","areas":["art"],"cnb":["art:3.2.4"],"prompt":"Clasifica cada textura: ¿es **táctil** (se siente) o **visual** (solo se ve)?","type":"sort","props":{"buckets":[{"id":"t","label":"Táctil","icon":"Hand","color":"var(--area-art)"},{"id":"v","label":"Visual","icon":"Eye","color":"var(--area-l1)"}],"items":[{"id":"z1","text":"Arena pegada con goma","bucket":"t"},{"id":"z2","text":"Punteado dibujado con lapicero","bucket":"v"},{"id":"z3","text":"Plastilina marcada con un tenedor","bucket":"t"},{"id":"z4","text":"Trama cruzada hecha con lápiz","bucket":"v"}]},"id":"s06-art-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["art"],"cnb":["art:3.2.4"],"type":"reflection","props":{"statements":["Creo texturas visuales con puntos, líneas y tramas","Creo texturas táctiles pegando, arrugando, enrollando, estampando y modelando","Trabajo con materiales reciclados de forma segura"],"commitments":["Terminaré mi animal dibujado con texturas","Haré mi cuadro en relieve","Guardaré materiales reciclados para futuras obras"]},"id":"s06-art-2-11"}],"kind":"materia","area":"art","day":4}},{"missionId":"s06","version":"cnb-sexto-4f8cfb28e3242783","lesson":{"id":"s06-mat-5","title":"Operaciones combinadas con conjuntos","icon":"Braces","minutes":15,"gancho":"Tres comisiones de la escuela: limpieza, huerto y reciclaje. ¿Quiénes están en limpieza y huerto, pero no en reciclaje? Para responder hay que combinar operaciones.","objetivos":["Resolver operaciones combinadas de conjuntos"],"resumen":["En una operación combinada, primero se resuelve lo que está entre paréntesis, igual que en aritmética.","Escribe el resultado de cada paso antes de seguir: así evitas errores.","Los paréntesis cambian el resultado: (A ∪ B) ∩ C no es lo mismo que A ∪ (B ∩ C).","Un diagrama de Venn de tres conjuntos ayuda a comprobar el resultado."],"media":{"id":"s06-mat-5-comisiones","kind":"image","title":"Las comisiones de la escuela","aspect":"4:3","alt":"Tres grupos de estudiantes trabajan en la escuela: uno barre el patio, otro riega el huerto y otro separa botellas en recipientes de reciclaje.","brief":"Ilustración de una escuela rural guatemalteca con tres escenas: la comisión de limpieza barre el patio, la de huerto riega hortalizas y la de reciclaje separa botellas y papel en recipientes de colores. Algunos niños aparecen en dos escenas (con la misma ropa) para sugerir que están en más de una comisión. Estilo plano, alegre, sin texto. Dimensiones: 1200x900."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:3.2.2"],"ambito":"conocer","title":"Cómo resolver operaciones combinadas","prompt":"Una **operación combinada** usa dos o más operaciones con conjuntos. Sigue estos pasos. Toca cada tarjeta.","type":"explain","props":{"icon":"ListOrdered","body":"Trabaja por partes y escribe cada resultado intermedio.","reveal":[{"icon":"Parentheses","front":"1. Paréntesis","back":"Resuelve primero lo que está entre paréntesis. Anota el resultado con un nombre, por ejemplo X."},{"icon":"ArrowRight","front":"2. Siguiente operación","back":"Usa ese resultado X con el conjunto que falta."},{"icon":"CircleDashed","front":"3. Comprueba con Venn","back":"Sombrea en un diagrama de tres conjuntos: primero el paréntesis, luego el resto."},{"icon":"Merge","front":"Recuerda","back":"∪ junta · ∩ deja los comunes · − quita lo del segundo · Δ deja lo que está en uno solo."}]},"id":"s06-mat-5-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.2"],"ambito":"hacer","title":"Ejemplo resuelto: (A ∩ B) ∪ C","prompt":"Usaremos A = {1, 2, 3, 4}, B = {3, 4, 5} y C = {4, 5, 6}.","type":"worked-example","props":{"icon":"Braces","problem":"Calcula **(A ∩ B) ∪ C**.","steps":[{"text":"Paréntesis: A ∩ B = **{3, 4}**.","why":"Son los elementos que están en A y en B."},{"text":"Ahora uno ese resultado con C: {3, 4} ∪ {4, 5, 6}."},{"text":"Junto sin repetir: **{3, 4, 5, 6}**."}],"answer":"(A ∩ B) ∪ C = {3, 4, 5, 6}.","tip":"Escribir el resultado del paréntesis evita confundirse en el segundo paso."},"id":"s06-mat-5-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.2"],"ambito":"conocer","prompt":"En aritmética, en (2 + 3) × 4 se resuelve primero el paréntesis. En **(A ∩ B) ∪ C**, ¿qué harías primero?","explain":"Igual que en aritmética: primero lo que está **entre paréntesis**, A ∩ B. Después, la unión con C.","type":"choice","props":{"options":[{"id":"a","text":"A ∩ B"},{"id":"b","text":"B ∪ C","feedback":"B ∪ C no está entre paréntesis. El paréntesis manda."},{"id":"c","text":"Da igual el orden","feedback":"El orden sí cambia el resultado, como verás hoy."}],"correct":["a"]},"id":"s06-mat-5-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.2"],"prompt":"Resuelve la operación combinada de conjuntos: con A = {1, 2, 3, 4}, B = {3, 4, 5} y C = {4, 5, 6}, ¿cuántos elementos tiene **(A ∪ B) − C**?","hint":"Primero A ∪ B. Después quítale los elementos que están en C.","explain":"A ∪ B = {1, 2, 3, 4, 5}. Le quito 4 y 5 (están en C): {1, 2, 3}. Tiene 3 elementos.","type":"number-input","props":{"answer":3,"misconceptions":[{"value":5,"msg":"Ese es A ∪ B. Falta quitarle los elementos que están en C."}]},"id":"s06-mat-5-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.2"],"ambito":"hacer","title":"Los paréntesis cambian el resultado","prompt":"Mismos conjuntos, mismas operaciones, paréntesis en distinto lugar.","type":"worked-example","props":{"icon":"Parentheses","problem":"Compara **(A ∪ B) ∩ C** con **A ∪ (B ∩ C)**.","steps":[{"text":"(A ∪ B) ∩ C: A ∪ B = {1, 2, 3, 4, 5}; con C quedan los comunes → **{4, 5}**."},{"text":"A ∪ (B ∩ C): B ∩ C = {4, 5}; unido con A → **{1, 2, 3, 4, 5}**."},{"text":"Los resultados son **distintos**.","why":"Por eso los paréntesis son obligatorios cuando hay dos operaciones diferentes."}],"answer":"(A ∪ B) ∩ C = {4, 5}, pero A ∪ (B ∩ C) = {1, 2, 3, 4, 5}."},"id":"s06-mat-5-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.2"],"prompt":"Con A = {1, 2, 3, 4}, B = {3, 4, 5} y C = {4, 5, 6}: ¿cuál es **A ∩ (B ∪ C)**?","hint":"Primero B ∪ C = {3, 4, 5, 6}. Luego busca qué tiene en común con A.","explain":"B ∪ C = {3, 4, 5, 6}. Sus comunes con A son 3 y 4: A ∩ (B ∪ C) = {3, 4}.","type":"choice","props":{"options":[{"id":"a","text":"{3, 4}"},{"id":"b","text":"{4}","feedback":"Ese es A ∩ B ∩ C. Aquí primero se une B con C."},{"id":"c","text":"{1, 2, 3, 4, 5, 6}","feedback":"Esa es la unión de los tres. La última operación es una intersección."}],"correct":["a"]},"id":"s06-mat-5-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:3.2.2","mat:3.2.3"],"ambito":"hacer","prompt":"Lee los datos de las comisiones y responde.","type":"reading","props":{"heading":"Las comisiones de sexto grado","genre":"Datos del grado","passage":"Supongamos que en sexto grado se formaron tres comisiones:\\n\\nLimpieza: L = {Ana, Beto, Carla, Dany}\\n\\nHuerto: H = {Carla, Dany, Emy, Fito}\\n\\nReciclaje: R = {Dany, Fito, Gaby}","questions":[{"q":"¿Quiénes están en limpieza y huerto, pero **no** en reciclaje? Es decir, (L ∩ H) − R.","options":[{"id":"a","text":"{Carla}"},{"id":"b","text":"{Carla, Dany}"},{"id":"c","text":"{Dany}"}],"correct":"a","why":"L ∩ H = {Carla, Dany}; a eso le quito a Dany, que está en R: queda {Carla}."},{"q":"¿Cuál es (H ∩ R) ∪ L?","options":[{"id":"a","text":"{Dany, Fito}"},{"id":"b","text":"{Ana, Beto, Carla, Dany, Fito}"},{"id":"c","text":"{Ana, Beto, Carla, Dany, Emy, Fito, Gaby}"}],"correct":"b","why":"H ∩ R = {Dany, Fito}; unido con L: {Ana, Beto, Carla, Dany, Fito}."},{"q":"¿Quiénes están en **solo una** de las comisiones de limpieza y huerto (L Δ H)?","options":[{"id":"a","text":"{Carla, Dany}"},{"id":"b","text":"{Ana, Beto}"},{"id":"c","text":"{Ana, Beto, Emy, Fito}"}],"correct":"c","why":"L − H = {Ana, Beto} y H − L = {Emy, Fito}; juntos: {Ana, Beto, Emy, Fito}."}]},"id":"s06-mat-5-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:3.2.2","mat:3.1.1"],"prompt":"Repaso: con L = {Ana, Beto, Carla, Dany} y H = {Carla, Dany, Emy, Fito}, el conjunto L ∩ H = {Carla, Dany}. ¿Cuántos **subconjuntos** tiene L ∩ H?","explain":"Un conjunto de 2 elementos tiene 4 subconjuntos: ∅, {Carla}, {Dany} y {Carla, Dany}.","type":"number-input","props":{"answer":4,"misconceptions":[{"value":2,"msg":"Olvidaste el vacío y el conjunto completo: ∅, {Carla}, {Dany}, {Carla, Dany}."}]},"id":"s06-mat-5-8"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:3.2.2"],"prompt":"Resuelve la operación combinada de conjuntos: P = {a, b, c, d}, Q = {c, d, e} y R = {d, e, f}. ¿Cuál es **(P ∩ Q) ∪ R**?","type":"choice","props":{"options":[{"id":"a","text":"{d}"},{"id":"b","text":"{c, d, e, f}"},{"id":"c","text":"{a, b, c, d, e, f}"}],"correct":["b"]},"id":"s06-mat-5-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:3.2.2"],"prompt":"Resuelve la operación combinada con P = {a, b, c, d}, Q = {c, d, e} y R = {d, e, f}: ¿cuántos elementos tiene **(P ∪ Q) − R**?","type":"number-input","props":{"answer":3},"id":"s06-mat-5-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["mat"],"cnb":[],"type":"reflection","props":{"statements":["Escribo conjuntos y reconozco subconjuntos","Encuentro todos los subconjuntos de un conjunto","Uso el diagrama de Venn para la unión, la intersección y las diferencias","Resuelvo operaciones combinadas respetando los paréntesis"],"commitments":["Haré un diagrama de Venn con los gustos de mi familia","Contaré de cuántas formas puedo combinar los ingredientes de mi refacción","Explicaré a alguien la diferencia entre ∪ y ∩"]},"id":"s06-mat-5-11"}],"kind":"materia","area":"mat","day":5}},{"missionId":"s06","version":"cnb-sexto-4101b9b3fd66ba88","lesson":{"id":"s06-fc-2","title":"Cuando la violencia se repite: acoso y ciberacoso","icon":"ShieldCheck","minutes":15,"gancho":"Una pelea de un día y una burla que se repite todos los días durante meses, ¿son lo mismo?","objetivos":["Diferenciar un conflicto entre iguales del acoso escolar"],"resumen":["Un conflicto es un desacuerdo entre personas; se puede resolver hablando. El acoso escolar es violencia que se repite, a propósito, contra alguien que tiene menos poder para defenderse.","El ciberacoso es acoso por teléfono o internet: llega a cualquier hora, lo ven muchas personas y es difícil de borrar.","Si te pasa: no respondas con violencia, guarda la evidencia, bloquea o reporta y cuéntalo a un adulto de confianza. No es tu culpa.","Los testigos tienen mucho poder: no reírse, no reenviar, acompañar a quien sufre y avisar a un adulto."],"media":{"id":"s06-fc-2-testigos","kind":"animation","title":"El poder de los testigos","aspect":"16:9","duration":50,"alt":"Animación: un niño recibe burlas en el corredor mientras otros miran; uno a uno, los que miran dejan de reír, se acercan a acompañarlo y una niña va a buscar a la maestra.","brief":"Animación 2D de 50 s, trazos suaves. Corredor de una escuela guatemalteca. Un niño es rodeado por dos compañeros que se burlan; alrededor, seis testigos (niñas y niños de distintos pueblos) ríen y graban con un teléfono. Una voz explica: \\"La mayoría no agrede… pero mira\\". Una testigo baja el teléfono, otro deja de reír, dos se acercan al niño y le dicen \\"vení con nosotros\\"; una niña va por la maestra. Los agresores se quedan sin público. Cierre en texto: \\"Sin público, el acoso pierde fuerza\\". Sin golpes visibles; narración en español, subtítulos."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"conocer","title":"Conflicto no es lo mismo que acoso","prompt":"Los **conflictos** (desacuerdos) son normales entre personas y se pueden resolver hablando. El **acoso escolar** es distinto: tiene **tres señales**. Toca cada tarjeta.","type":"explain","props":{"icon":"ShieldCheck","body":"Si ves las tres señales juntas, no basta con \\"arreglarse entre ellos\\": se necesita la **ayuda de un adulto**.","reveal":[{"icon":"RefreshCw","front":"1. Se repite","back":"No es una vez: pasa **muchas veces**, durante semanas o meses."},{"icon":"Target","front":"2. Es a propósito","back":"Quien agrede **quiere** hacer daño, humillar o dar miedo. No es un accidente."},{"icon":"Scale","front":"3. Hay desigualdad de poder","back":"Quien sufre tiene **menos fuerza o apoyo**: es más pequeño, está solo, es nuevo o el grupo está en su contra."},{"icon":"MessagesSquare","front":"En cambio, un conflicto…","back":"Es un desacuerdo **entre iguales** (por un turno, un lápiz, una regla del juego) que se puede resolver con diálogo."}]},"id":"s06-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"conocer","title":"El ciberacoso","prompt":"El **ciberacoso** es acoso por **teléfono o internet**. Tiene sus propias características. Toca cada tarjeta.","type":"explain","props":{"icon":"Smartphone","body":"Detrás de cada pantalla hay una persona con sentimientos. Lo que publicas **se queda** y puede llegar a muchos.","reveal":[{"icon":"Clock","front":"Llega a cualquier hora","back":"No termina al salir de la escuela: sigue en la casa, de noche y los fines de semana."},{"icon":"Users","front":"Lo ven muchas personas","back":"Un mensaje o una foto se reenvía en segundos a decenas o cientos de personas."},{"icon":"Lock","front":"Es difícil de borrar","back":"Aunque se borre, alguien pudo **guardarlo**. Por eso nunca compartas fotos de otros sin permiso."},{"icon":"ShieldCheck","front":"Qué hacer si te pasa","back":"**No respondas** con insultos, **guarda la evidencia** (captura de pantalla), **bloquea o reporta** y **cuéntalo** a un adulto de confianza. No es tu culpa."}]},"id":"s06-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: el caso del chat","prompt":"Mira cómo Ana y un testigo, Luis, enfrentaron un caso de ciberacoso.","type":"worked-example","props":{"icon":"MessageCircle","problem":"En el chat del grado, alguien crea una encuesta: \\"¿Quién es la más fea del grado?\\" y pone la foto de Ana. Varios votan y mandan risas. Ana lo ve en la noche.","steps":[{"text":"Ana **no responde** con insultos, aunque siente mucha rabia y tristeza.","why":"Responder con violencia hace crecer el problema y puede meterla en problemas a ella."},{"text":"Ana **guarda la evidencia**: toma capturas de pantalla con la fecha."},{"text":"Ana **se sale del chat** y **se lo cuenta a su mamá** esa misma noche."},{"text":"Luis, que estaba en el chat, **no vota ni reenvía**; le escribe a Ana: \\"Eso está muy mal, cuenta conmigo\\", y avisa a la maestra.","why":"Un testigo que no se ríe y avisa le quita público al acoso."},{"text":"La mamá y la maestra hablan con la dirección; la escuela aplica sus **normas de convivencia** y habla con quienes participaron."}],"answer":"Ana se protegió y **pidió ayuda**; Luis usó su poder de **testigo**. Juntos, con los adultos, detuvieron el ciberacoso.","tip":"No respondo → guardo evidencia → bloqueo o reporto → se lo cuento a un adulto de confianza."},"id":"s06-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"convivir","prompt":"Desde hace tres meses, dos compañeros esconden la refacción de Pablo, que es el más pequeño del grado, y se ríen cuando él la busca. ¿Qué crees que es?","explain":"Es **acoso escolar**: se repite, es a propósito y Pablo tiene menos poder para defenderse. Hoy aprenderás a distinguirlo de un simple conflicto.","type":"choice","props":{"options":[{"id":"a","text":"Un juego sin importancia","icon":"Smile","feedback":"Un juego es divertido para todos. Aquí solo se ríen quienes esconden la refacción."},{"id":"b","text":"Algo más serio que se repite y hace daño","icon":"ShieldCheck"},{"id":"c","text":"Culpa de Pablo por ser pequeño","icon":"User","feedback":"Nunca es culpa de quien sufre la violencia."}],"correct":["b"]},"id":"s06-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:4.2.1"],"prompt":"Clasifica: ¿es un **conflicto** que se puede resolver hablando, o es **acoso** que necesita ayuda de un adulto?","hint":"Busca las tres señales: ¿se repite?, ¿es a propósito?, ¿uno tiene menos poder?","explain":"Los conflictos entre iguales se resuelven con diálogo. El acoso, con sus tres señales, necesita que intervenga un adulto.","type":"sort","props":{"buckets":[{"id":"con","label":"Conflicto","icon":"MessagesSquare","color":"var(--c-ok)"},{"id":"aco","label":"Acoso","icon":"ShieldCheck","color":"var(--c-bad)"}],"items":[{"id":"k1","text":"Dos amigas discuten un día porque las dos querían ser capitanas","bucket":"con"},{"id":"k2","text":"Un grupo de sexto le quita el dinero de la refacción a un niño de segundo cada semana","bucket":"aco"},{"id":"k3","text":"Dos equipos no se ponen de acuerdo sobre si fue gol","bucket":"con"},{"id":"k4","text":"Desde que llegó, a Lesbia le imitan su forma de hablar todos los días","bucket":"aco","feedback":"Se repite, es a propósito y ella es nueva: tiene las tres señales."},{"id":"k5","text":"Dos compañeros discuten por quién usa primero la computadora","bucket":"con"}]},"id":"s06-fc-2-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:4.2.1"],"prompt":"Ordena lo que conviene hacer si **te pasa** ciberacoso.","hint":"Primero te proteges sin empeorar las cosas; al final buscas ayuda con los adultos.","explain":"No responder → guardar evidencia → bloquear o reportar → contarlo a un adulto de confianza → buscar juntos apoyo en la escuela.","type":"order","props":{"labels":{"start":"Primero","end":"Después"},"items":[{"id":"c1","text":"No responder con insultos ni amenazas","icon":"VolumeX"},{"id":"c2","text":"Guardar la evidencia con capturas de pantalla","icon":"Camera"},{"id":"c3","text":"Bloquear o reportar a quien agrede","icon":"Lock"},{"id":"c4","text":"Contarlo a un adulto de confianza","icon":"MessageCircle"},{"id":"c5","text":"Buscar juntos el apoyo de la escuela","icon":"School"}]},"id":"s06-fc-2-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"convivir","prompt":"Eres testigo. ¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Smartphone","text":"Te llega un video donde se burlan de Walter, un compañero, porque se cayó en educación física. Te dicen: \\"¡Reenvialo a todos, está buenísimo!\\"."},"options":[{"id":"a","icon":"Share2","text":"Reenviarlo: total, ya lo vieron muchos","consequence":"El video llega a otros grados. Walter no quiere volver a la escuela. Tú fuiste parte de la cadena.","values":["Indiferencia"],"constructive":false},{"id":"b","icon":"VolumeX","text":"No reenviarlo y pedir en el chat que lo borren","consequence":"Algunos se molestan, pero otros te apoyan y el video se borra del chat. La cadena se corta contigo.","values":["Respeto","Valentía"],"constructive":true},{"id":"c","icon":"HeartHandshake","text":"No reenviarlo, escribirle a Walter para apoyarlo y avisar a la maestra","consequence":"Walter se siente acompañado. La maestra habla con el grado sobre el respeto en redes.","values":["Solidaridad","Responsabilidad"],"constructive":true}]},"id":"s06-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"convivir","prompt":"Nidia sufre acoso y le da vergüenza contarlo. ¿Qué **adulto de confianza** puede ayudarla? Marca **todas** las opciones correctas.","explain":"Un adulto de confianza es alguien que te escucha, te cree y puede actuar: familia, docentes, dirección u orientación. Si hay peligro inmediato, se puede llamar a la **Policía Nacional Civil al 110**.","type":"choice","props":{"multiple":true,"options":[{"id":"a","text":"Su mamá, su papá o la persona que la cuida","icon":"Home"},{"id":"b","text":"Su maestra o la directora de la escuela","icon":"School"},{"id":"c","text":"Un desconocido que conoció en internet","icon":"Smartphone","feedback":"Un desconocido de internet no es un adulto de confianza. Busca personas que conoces y que te cuidan."},{"id":"d","text":"Una tía o un abuelo que la escucha","icon":"HeartHandshake"}],"correct":["a","b","d"]},"id":"s06-fc-2-8"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:4.2.1"],"prompt":"¿Cuál situación es **acoso escolar** y no un simple conflicto?","type":"choice","props":{"options":[{"id":"a","text":"Todos los días, un grupo le dice apodos a una niña nueva y no la deja entrar al salón"},{"id":"b","text":"Dos amigos discuten una vez sobre las reglas de un juego y luego se ponen de acuerdo"},{"id":"c","text":"Dos equipos no se ponen de acuerdo sobre la hora del partido"}],"correct":["a"]},"id":"s06-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:4.2.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Si sufres ciberacoso, conviene guardar la evidencia y contarlo a un adulto de confianza.","answer":true},{"text":"Los testigos no pueden hacer nada para detener el acoso.","answer":false,"why":"Los testigos pueden no reírse, no reenviar, acompañar a quien sufre y avisar a un adulto."},{"text":"El acoso escolar se repite, es a propósito y hay desigualdad de poder.","answer":true},{"text":"Si alguien sufre acoso, es porque se lo buscó.","answer":false,"why":"Nunca es culpa de quien sufre la violencia."}]},"id":"s06-fc-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["fc"],"cnb":["fc:4.2.1"],"type":"reflection","props":{"statements":["Reconozco la cultura de paz y la de violencia en mi casa, escuela y comunidad","Distingo un conflicto del acoso escolar","Sé qué hacer y a quién pedir ayuda ante el acoso y el ciberacoso"],"commitments":["No reenviaré nada que se burle de otra persona","Llamaré a mis compañeros por su nombre, no por apodos","Si veo acoso, acompañaré a quien lo sufre y avisaré a un adulto"]},"id":"s06-fc-2-11"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s06","version":"cnb-sexto-d4625d3519891ddd","lesson":{"id":"s06-ef-2","title":"Preparado y en calma: vestuario, respiración y relajación","icon":"Wind","minutes":15,"gancho":"¿Has intentado correr con zapatos de vestir o con los cordones sueltos? ¿Y te ha pasado que antes de un partido o un examen el corazón te late muy rápido?","objetivos":["Aplicar preparación y recuperación seguras en la actividad física"],"resumen":["Vestuario para la actividad física: ropa cómoda y fresca que deje mover el cuerpo, calzado deportivo con suela antideslizante y bien amarrado, cabello recogido y sin aretes, collares ni objetos en los bolsillos.","Según el lugar y el clima: al sol, gorra o sombrero y bloqueador; al frío, varias capas que te puedas quitar; en el monte, pantalón largo, manga larga y botas o zapatos cerrados.","Respiración abdominal lenta: inhala por la nariz inflando el abdomen (4 tiempos) y exhala despacio por la boca (4 a 6 tiempos). Calma el cuerpo y las emociones.","Relajación de tensión y soltura: aprieta un grupo de músculos 5 segundos y suéltalo 10 segundos, notando la diferencia. Ayuda después del ejercicio y en momentos de nervios o enojo."],"media":{"id":"s06-ef-2-respiracion","kind":"animation","title":"Respira como un globo","aspect":"16:9","duration":60,"alt":"Una niña acostada con un peluche sobre el abdomen: al inhalar el peluche sube como un globo que se infla; al exhalar despacio, baja. Un contador marca 4 tiempos para inhalar y 6 para exhalar.","brief":"Animación 2D tranquila de 60 s, colores suaves. (1) Una niña acostada boca arriba en un petate con un peluche sobre el abdomen. (2) Un globo dibujado dentro del abdomen se infla al inhalar por la nariz (contador 1-2-3-4) y se desinfla al exhalar por la boca (contador 1-2-3-4-5-6); el peluche sube y baja. (3) Un corazón en una esquina late rápido al inicio y más lento al final (sin cifras). (4) Texto final: \\"Inhala 4 · Exhala 6\\". Voz narradora calmada en español, subtítulos. Música ambiental muy suave."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"conocer","title":"El vestuario adecuado","prompt":"La ropa correcta depende de **qué actividad** harás, **dónde** y con **qué clima**. Mira la ilustración y toca cada tarjeta.","media":{"id":"s06-ef-2-vestuario","kind":"image","title":"Vestidos para cada actividad","aspect":"16:9","alt":"Tres niñas y niños vestidos para distintas actividades: uno para la cancha al sol con gorra, camiseta holgada y tenis; otra para una mañana fría con capas; otro para una siembra en el monte con pantalón largo, manga larga, sombrero y botas.","brief":"Ilustración en tres paneles con fondo guatemalteco: (1) cancha escolar al sol: gorra, camiseta clara holgada, pantaloneta, tenis amarrados, pachón de agua; (2) mañana fría en el altiplano: camiseta, suéter y chumpa en capas, pants y tenis; (3) jornada de siembra en el monte: sombrero, camisa manga larga, pantalón largo, botas de hule, bloqueador. Un pequeño recuadro tachado con chancletas, collar y zapatos de vestir. Sin marcas visibles en la ropa. Diversidad de pueblos y géneros. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"Shirt","body":"Regla general: **cómodo, seguro y apropiado al clima**. No hace falta ropa cara: basta con que cumpla su función.","reveal":[{"icon":"Shirt","front":"Ropa","back":"**Cómoda y holgada**, de tela que deje pasar el aire (como el algodón). Que no apriete ni se enrede."},{"icon":"Footprints","front":"Calzado","back":"**Tenis o zapatos deportivos** con suela que no resbale, **bien amarrados**. Nada de chancletas ni zapatos de vestir."},{"icon":"Sun","front":"Sol y calor","back":"Gorra o sombrero, **bloqueador** y ropa de colores claros. Lleva **agua**."},{"icon":"Snowflake","front":"Frío","back":"Varias **capas** (camiseta, suéter, chumpa) que te puedas quitar al entrar en calor y volver a poner al terminar."},{"icon":"TreePine","front":"Monte o siembra","back":"**Pantalón largo**, **manga larga** y zapatos cerrados o botas: te protegen de espinas, piedras e insectos."},{"icon":"Gem","front":"Sin accesorios","back":"Quítate **aretes, collares, relojes** y saca objetos de los bolsillos. Recoge el cabello largo. Evitas golpes y rasguños."}]},"id":"s06-ef-2-1"},{"fase":"construir","areas":["ef","cnt"],"cnb":["ef:3.1.2"],"ambito":"ser","title":"La respiración que calma","prompt":"Cuando haces ejercicio o sientes nervios, respiras rápido y el corazón se acelera. Puedes **ayudar a tu cuerpo a calmarse** con la respiración. Mira la animación y toca cada tarjeta.","type":"explain","props":{"icon":"Wind","body":"La respiración **abdominal lenta** usa el **diafragma**, un músculo debajo de los pulmones. Al respirar despacio y profundo, el cuerpo recibe la señal de que puede calmarse.","reveal":[{"icon":"Wind","front":"Inhala","back":"Por la **nariz**, contando **4**, inflando el **abdomen** como un globo (los hombros no suben)."},{"icon":"Hourglass","front":"Exhala","back":"Por la **boca**, despacio, contando **4 a 6**, desinflando el globo. Exhalar más largo que inhalar ayuda a calmarse."},{"icon":"Repeat","front":"Repite","back":"Haz de **5 a 10** respiraciones. Puedes hacerlo sentado, de pie o acostado."},{"icon":"Heart","front":"¿Cuándo?","back":"Después del ejercicio, antes de un partido o una prueba, cuando sientes enojo o miedo. Es tu herramienta para el **equilibrio emocional**."}]},"id":"s06-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:3.1.2"],"ambito":"ser","title":"Ejemplo resuelto: la relajación de tensión y soltura","prompt":"Otra técnica: **tensar y soltar** los músculos. Mira cómo la usa Tomás después de un partido en el que se enojó.","type":"worked-example","props":{"icon":"Smile","problem":"Tomás perdió un partido y siente los hombros duros, los puños apretados y la respiración agitada.","steps":[{"text":"Se sienta cómodo en un lugar tranquilo y hace **3 respiraciones abdominales** lentas."},{"text":"**Manos:** aprieta los puños fuerte **5 segundos**… y los **suelta 10 segundos**, notando cómo se aflojan.","why":"Al sentir la diferencia entre tensión y soltura, el cuerpo aprende a relajarse."},{"text":"**Hombros:** los sube hacia las orejas 5 segundos… y los deja caer 10 segundos."},{"text":"**Cara:** arruga la cara 5 segundos… y la afloja 10 segundos."},{"text":"Termina con 3 respiraciones más y nota cómo se siente: más tranquilo y listo para hablar de lo que pasó."}],"answer":"Tensar **5 s** y soltar **10 s** cada grupo de músculos, con respiraciones lentas al inicio y al final, ayuda a recuperar la calma.","tip":"Aprieta con fuerza, pero sin dolor. Si algo duele, no lo tenses tanto."},"id":"s06-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"conocer","prompt":"Mañana hay clase de Educación Física en la cancha, a pleno sol. ¿Qué te pondrías?","explain":"Ropa **cómoda y fresca**, **tenis bien amarrados** y **gorra**. El vestuario adecuado te protege y te deja moverte con libertad.","type":"choice","props":{"options":[{"id":"a","text":"Ropa cómoda y fresca, tenis bien amarrados y gorra","icon":"Shirt"},{"id":"b","text":"Pantalón de vestir, zapatos lustrados y reloj","icon":"Briefcase","feedback":"Esa ropa limita el movimiento y los zapatos de vestir resbalan."},{"id":"c","text":"Chancletas para ir más fresco","icon":"Footprints","feedback":"Las chancletas se salen y no protegen los pies: aumentan el riesgo de golpes y torceduras."}],"correct":["a"]},"id":"s06-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"conocer","prompt":"Clasifica cada prenda o accesorio para una clase de Educación Física en la cancha.","hint":"Piensa: ¿me deja mover?, ¿me protege?, ¿puede golpearme o hacerme caer?","explain":"Lo adecuado es cómodo, seguro y según el clima. Los accesorios y el calzado inadecuado pueden causar lesiones.","type":"sort","props":{"buckets":[{"id":"si","label":"Adecuado","icon":"Check","color":"var(--c-ok)"},{"id":"no","label":"No adecuado","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"v1","text":"Tenis bien amarrados","bucket":"si"},{"id":"v2","text":"Collar largo","bucket":"no"},{"id":"v3","text":"Camiseta de algodón holgada","bucket":"si"},{"id":"v4","text":"Chancletas","bucket":"no"},{"id":"v5","text":"Gorra y bloqueador en día de sol","bucket":"si"},{"id":"v6","text":"Pantalón de vestir ajustado","bucket":"no"}]},"id":"s06-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:3.1.2"],"ambito":"ser","prompt":"¡Mide cómo te calmas! **Parte 1:** mide tu pulso en reposo. **Parte 2:** haz 1 minuto de actividad intensa (trote en tu lugar con rodillas arriba y saltos suaves) y mide tu pulso. **Parte 3:** siéntate y haz respiración abdominal (inhala 4, exhala 6) y la relajación de tensión y soltura de manos, hombros y cara; mide otra vez. Observa cómo tu pulso baja. **Poco espacio:** todo en tu lugar. **Adaptación:** la actividad intensa puede ser con los brazos, sentado.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de la actividad intensa","exercise":{"name":"Trote con rodillas arriba y saltos suaves","icon":"Activity","seconds":60}},{"label":"Después de respirar y relajarte","exercise":{"name":"Respiración 4-6 y tensión-soltura","icon":"Wind","seconds":90}}]},"id":"s06-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"hacer","prompt":"Como preparación para la actividad física del sábado hay una **jornada de siembra** en la montaña: habrá sol, tierra, espinas y piedras. ¿Qué vestuario es adecuado? **Elige todas las correctas.**","explain":"En el monte hay que proteger la piel y los pies: manga y pantalón largos, zapatos cerrados, sombrero y bloqueador. Las chancletas y los shorts dejan la piel expuesta a espinas e insectos.","type":"choice","props":{"multiple":true,"options":[{"id":"a","text":"Pantalón largo y camisa de manga larga"},{"id":"b","text":"Botas o zapatos cerrados"},{"id":"c","text":"Sombrero o gorra y bloqueador"},{"id":"d","text":"Chancletas y short","feedback":"Dejan los pies y las piernas expuestos a espinas, piedras e insectos."}],"correct":["a","b","c"]},"id":"s06-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:3.1.2"],"ambito":"ser","prompt":"Como recuperación emocional antes de volver a la actividad física, ¿qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Heart","text":"Faltan 5 minutos para la final del torneo de pases. **Ana** siente el corazón acelerado, las manos sudadas y dice: \\"Mejor no juego, me voy a equivocar\\"."},"options":[{"id":"a","icon":"X","text":"Decirle: \\"Si tienes miedo, mejor quédate afuera\\"","consequence":"Ana se pierde la final y se queda con la idea de que los nervios no se pueden manejar.","values":["Evitar"],"constructive":false},{"id":"b","icon":"Wind","text":"Invitarla a hacer juntas 5 respiraciones abdominales y a soltar hombros y manos","consequence":"Ana se calma un poco, siente apoyo y decide jugar. Los nervios no desaparecen del todo, pero ya no la controlan.","values":["Empatía","Autocontrol","Compañerismo"],"constructive":true},{"id":"c","icon":"MessageCircle","text":"Recordarle que equivocarse es parte de aprender y que el equipo la apoya","consequence":"Ana se siente acompañada. Con palabras de apoyo y respiración, la confianza crece.","values":["Apoyo","Respeto"],"constructive":true}]},"id":"s06-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:3.1.2"],"prompt":"Durante la recuperación de la actividad física, en la respiración abdominal lenta, ¿qué parte del cuerpo se infla al inhalar?","type":"choice","props":{"options":[{"id":"a","text":"El abdomen"},{"id":"b","text":"Los hombros, que suben hasta las orejas"},{"id":"c","text":"Las mejillas"}],"correct":["a"]},"id":"s06-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:3.1.6","ef:3.1.2"],"prompt":"Sobre preparación y recuperación para la actividad física, ¿verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Para hacer ejercicio conviene quitarse aretes, collares y relojes.","answer":true},{"text":"Con frío es mejor usar varias capas de ropa que te puedas quitar.","answer":true},{"text":"En la relajación de tensión y soltura se aprieta el músculo hasta que duela.","answer":false,"why":"Se aprieta con fuerza pero sin dolor, y luego se suelta."},{"text":"Exhalar despacio y más largo que la inhalación ayuda a calmarse.","answer":true}]},"id":"s06-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["ef"],"cnb":["ef:3.1.2"],"type":"reflection","props":{"statements":["Paso el balón con la parte interna y externa de cada pie","Elijo el vestuario adecuado para cada actividad","Uso la respiración y la relajación para calmarme"],"commitments":["Revisaré mi ropa y mis cordones antes de cada clase","Practicaré 5 respiraciones lentas antes de dormir","Usaré la respiración cuando sienta nervios o enojo"]},"id":"s06-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s06","version":"cnb-sexto-d9bb7b8a67c3fcea","lesson":{"id":"s06-d5-taller","kind":"taller","day":5,"title":"Una refacción local que nutre","icon":"CookingPot","minutes":20,"gancho":"El comité necesita una propuesta adaptable para 12 personas. ¿Cómo puede justificar el menú, comparar opciones y comprobar que el costo cabe en el escenario?","objetivos":["Integrar evidencia de Ciencias, Matemáticas, L1 y Productividad en una propuesta de refacción local adaptable"],"resumen":["El producto contiene un menú justificado, una comparación de conjuntos, un presupuesto simple y un esquema del proyecto.","Los alimentos pueden aportar varios nutrientes; la justificación describe aportes sin prometer resultados de salud.","Los precios del escenario son ilustrativos y no representan precios actuales del mercado.","La propuesta consulta alergias, intolerancias y restricciones, y separa la planificación de cualquier preparación real con apoyo adulto."],"media":{"id":"s06-taller-ficha","kind":"image","title":"Ficha de propuesta de refacción","aspect":"4:3","alt":"Ficha dividida en menú justificado, comparación de conjuntos, presupuesto y esquema del proyecto, con una franja para alergias y restricciones.","brief":"Mock honesto de una ficha imprimible aún sin respuestas. Cuatro zonas rotuladas: menú justificado, comparación de conjuntos, presupuesto y esquema del proyecto. Franja \\"consultar alergias, intolerancias y restricciones\\" y nota \\"precios ilustrativos del escenario\\". Espacio real para cálculos y revisión; no simular evidencia estudiantil. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:5.3.1"],"ambito":"conocer","title":"1 min · Lean el encargo","prompt":"**1 min.** Revisen el encargo para 12 personas y los límites de la propuesta.","type":"explain","props":{"icon":"ClipboardList","body":"Trabajarán con alimentos posibles del escenario, no con una lista universal. Los **precios son ilustrativos**, no datos actuales del mercado, y el límite del presupuesto del escenario es **Q50**. Hoy diseñan en papel; no cocinan. Una preparación posterior debe consultar alergias, intolerancias y restricciones, lavarse las manos y contar con apoyo o supervisión adulta para calor, cuchillos o cocción."},"id":"s06-d5-taller-1"},{"fase":"construir","areas":["l1","pyd"],"cnb":["l1:8.2.1","pyd:4.1.1"],"ambito":"hacer","title":"1 min · Organicen la hoja","prompt":"**1 min.** En una hoja de papel o en el cuaderno, escriban cuatro encabezados: menú, conjuntos, presupuesto y plan.","type":"project","props":{"goal":"Registrar una propuesta que otra persona pueda revisar.","steps":[{"title":"Datos iniciales","detail":"Anoten el nombre del equipo y marquen disponibilidad por confirmar."},{"title":"Condiciones","detail":"Mantengan visible la consulta de alergias, intolerancias y restricciones."}],"evidence":"Lista de cotejo para comprobar que el papel tiene equipo, encabezados y condiciones; esta actividad no captura el escrito.","rubric":["El papel o cuaderno tiene los cuatro encabezados","La ficha no supone disponibilidad ni seguridad alimentaria"]},"id":"s06-d5-taller-2"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:3.2.1"],"ambito":"hacer","title":"1 min · Comparen conjuntos","prompt":"**1 min.** L = opciones confirmadas disponibles en el escenario = {tortilla, frijol, banano, papaya, agua segura}. P = ítems **clasificados en el escenario en el grupo de proteína** = {frijol, huevo, queso, pepitoria}. Esta regla no afirma que los demás alimentos tengan cero proteína: los alimentos pueden aportar varios nutrientes. ¿Cuál es **L ∩ P**, la intersección?","type":"choice","props":{"options":[{"id":"a","text":"{frijol}"},{"id":"b","text":"{tortilla, frijol, banano, papaya, huevo, queso, pepitoria}"},{"id":"c","text":"{huevo, queso, pepitoria}"}],"correct":["a"]},"id":"s06-d5-taller-3"},{"fase":"aplicar","areas":["cnt","l1"],"cnb":["cnt:5.3.1","l1:8.2.1"],"ambito":"hacer","title":"3 min · Justifiquen el menú","prompt":"**3 min.** Completen el menú base del escenario y una alternativa por restricción o disponibilidad.","type":"project","props":{"goal":"Escribir un menú justificable con lenguaje descriptivo y sin juicios morales.","steps":[{"title":"Menú base","detail":"M = ingredientes seleccionados = {tortilla, frijol, banano, agua segura}. Propongan 2 tortillas con frijol cocido, 1 banano y agua segura. Justifiquen con hábitos: variedad, agua segura e higiene."},{"title":"Alternativa","detail":"Si una alergia, intolerancia, restricción o práctica familiar impide un ingrediente, anoten \\"consultar y sustituir por una opción disponible con aporte semejante\\"; no inventen que una opción es segura para todas las personas."}],"evidence":"Lista de cotejo del menú escrito en papel; el proyecto no captura el texto.","rubric":["La razón usa criterios de hábitos nutricionales","La alternativa respeta restricciones y disponibilidad"]},"id":"s06-d5-taller-4"},{"fase":"aplicar","areas":["mat","pyd"],"cnb":["pyd:4.1.1"],"ambito":"hacer","title":"3 min · Calculen el presupuesto","prompt":"**3 min. Precios ilustrativos del escenario**, no precios actuales:\\n- 24 tortillas a **Q0.50** cada una\\n- 3 libras de frijol a **Q8** cada libra\\n- 12 bananos a **Q1** cada uno\\n- 12 vasos de agua segura disponible en la escuela a **Q0** cada uno\\n**Límite del escenario: Q50.**\\nEn la tabla anoten cantidad, precio, subtotal de cada rubro y el total. ¿Cuál es el costo total para 12 refacciones?","type":"number-input","props":{"answer":48,"unit":"quetzales"},"id":"s06-d5-taller-5"},{"fase":"aplicar","areas":["pyd","l1"],"cnb":["pyd:4.1.1","pyd:4.3.1","l1:8.2.1"],"ambito":"emprender","title":"3 min · Tracen el esquema del proyecto","prompt":"**3 min.** Completen el esquema conciso del proyecto sin pasar todavía a preparar alimentos.","type":"project","props":{"goal":"Convertir la propuesta en un proyecto verificable.","steps":[{"title":"Objetivo y actividades","detail":"Completen: objetivo; actividad 1, confirmar restricciones y disponibilidad; actividad 2, actualizar precios y presentar la propuesta."},{"title":"Responsable, fecha y revisión","detail":"Anoten un responsable, una fecha y cómo se hará la revisión. La preparación real requiere autorización y apoyo adulto."}],"evidence":"Lista de cotejo del esquema escrito en papel; el proyecto no captura sus campos.","rubric":["Las actividades responden al objetivo","El plan distingue propuesta de preparación real"]},"id":"s06-d5-taller-6"},{"fase":"aplicar","areas":["l1","cnt"],"cnb":["l1:8.2.1","cnt:5.3.1"],"ambito":"hacer","title":"2 min · Redacten la propuesta","prompt":"**2 min.** Escriban una propuesta de **14 a 18 palabras** que conecte menú, aportes y costo total.","type":"short-answer","props":{"minWords":16,"placeholder":"Proponemos... por sus aportes; con precios ilustrativos, el total es...","model":"Proponemos tortilla, frijol, banano y agua segura por su variedad, aporte nutritivo e higiene; con los precios ilustrativos suministrados, el total calculado es Q48.","rubric":["Justificamos el menú con hábitos nutricionales","Comunicamos el total ilustrativo en 14 a 18 palabras"]},"id":"s06-d5-taller-7"},{"fase":"aplicar","areas":["cnt","mat","l1","pyd"],"cnb":["cnt:5.3.1","mat:3.2.1","l1:8.2.1","pyd:4.1.1"],"ambito":"hacer","title":"2 min · Revisión entre pares","prompt":"**2 min.** Intercambien fichas. Apliquen **un criterio**: cada ingrediente seleccionado del menú está clasificado en los conjuntos cuando corresponde y cada ingrediente seleccionado aparece en el presupuesto; los conjuntos pueden incluir alternativas no seleccionadas. Marquen **una revisión** y hagan **una corrección**.","type":"project","props":{"goal":"Corregir una incoherencia antes de entregar.","steps":[{"title":"Criterio único","detail":"M está contenido en L; el frijol seleccionado también está en P; cada ingrediente de M aparece en el presupuesto. P puede conservar alternativas no seleccionadas."},{"title":"Corrección","detail":"Cambien una palabra, ingrediente o cifra solo si el criterio no se cumple."}],"evidence":"Lista de cotejo de una corrección hecha en el papel; el proyecto no captura el artefacto.","rubric":["La revisión usa el criterio indicado","La corrección alinea el producto"]},"id":"s06-d5-taller-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:5.3.1"],"title":"1 min · Salida de cuidado","prompt":"**1 min.** Una compañera informa una alergia. ¿Qué debe decir la propuesta?","type":"choice","props":{"options":[{"id":"a","text":"Confirmar la restricción con la familia o escuela y elegir una alternativa segura antes de preparar"},{"id":"b","text":"Servir una porción pequeña porque así no habrá reacción"},{"id":"c","text":"Quitar el rótulo para no preocupar al grupo"}],"correct":["a"]},"id":"s06-d5-taller-9"},{"fase":"reflexionar","areas":["cnt","mat","l1","pyd"],"cnb":["cnt:5.3.1","mat:3.2.1","l1:8.2.1","pyd:4.3.1"],"ambito":"ser","title":"1 min · Reflexión","prompt":"**1 min.** Revisa la evidencia y elige el próximo paso más honesto.","type":"reflection","props":{"statements":["Justifiqué el menú sin prometer resultados de salud","Comprobé los conjuntos, los subtotales y que el costo total del escenario no supera el límite del presupuesto","Incluí restricciones, disponibilidad y preparación segura"],"commitments":["Preguntaré qué opciones y restricciones existen antes de proponer un menú real","Actualizaré precios con una fuente local antes de presentar el presupuesto como real"]},"id":"s06-d5-taller-10"}]}},{"missionId":"s06","version":"cnb-sexto-dd696ba9e2ebcef5","lesson":{"id":"s06-d5-reto","kind":"reto","day":5,"title":"Reto de la semana 6","icon":"Trophy","minutes":14,"objetivos":["Transferir lo aprendido en las diez áreas a situaciones nuevas"],"resumen":["Resolví situaciones nuevas sin pistas ni respuestas reutilizadas."],"media":{"id":"s06-reto-mesa","kind":"image","title":"Mesa de revisión interdisciplinaria","aspect":"16:9","alt":"Mesa con tarjetas de conjuntos, una propuesta, una cronología, texturas, instrucciones bilingües, un balón y una tabla de proyecto.","brief":"Imagen cenital con evidencias nuevas para diez áreas: tarjetas de semillas, oración de propuesta, ficha de nutrientes, cronología, pares de palabras, instrucciones en inglés, caso ciudadano, patrón de textura, balón con flechas y tabla de proyecto. Objetos reconocibles; no usar formas genéricas como sustitutos. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"comprobar","areas":["mat"],"cnb":["mat:3.2.1"],"prompt":"A = {pepitoria, ajonjolí, manía} y B = {ajonjolí, cacao}. ¿Cuál es A ∩ B?","type":"choice","props":{"options":[{"id":"a","text":"{ajonjolí}"},{"id":"b","text":"{pepitoria, manía, cacao}"},{"id":"c","text":"∅"}],"correct":["a"]},"id":"s06-d5-reto-1"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:7.2.6"],"prompt":"Marca el sujeto de la oración: “Las familias del comité revisaron la propuesta.”","type":"highlight","props":{"text":"{Las familias del comité} revisaron la propuesta.","target":"sujeto"},"id":"s06-d5-reto-2"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:5.3.1"],"prompt":"El registro de Marta dice: lunes comió antes de clase; martes, al final de la mañana; miércoles, antes de clase; jueves no registró hora. ¿Qué conclusión usa el criterio de regularidad con prudencia?","type":"choice","props":{"options":[{"id":"a","text":"El horario varió y falta un dato; conviene completar el registro antes de proponer un cambio posible"},{"id":"b","text":"Marta debe recibir una prohibición por el dato del jueves"},{"id":"c","text":"Cuatro días bastan para diagnosticar su salud"}],"correct":["a"]},"id":"s06-d5-reto-3"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:6.7.1","ccss:6.7.4"],"prompt":"Fuente suministrada: Argentina volvió a un gobierno constitucional civil en 1983 después de una dictadura; se ampliaron libertades políticas, mientras inflación, deuda y desigualdad siguieron afectando a habitantes. Organiza la evidencia.","type":"sort","props":{"buckets":[{"id":"a","label":"Avance de apertura democrática","icon":"Vote","color":"var(--area-ccss)"},{"id":"c","label":"Condición socioeconómica persistente","icon":"ChartNoAxesCombined","color":"var(--c-maiz-strong)"}],"items":[{"id":"x","text":"Regreso de autoridades civiles elegidas","bucket":"a"},{"id":"y","text":"Reapertura de partidos y libertades políticas","bucket":"a"},{"id":"z","text":"Inflación que reduce el poder de compra","bucket":"c"},{"id":"w","text":"Acceso desigual a servicios que continúa","bucket":"c"}]},"id":"s06-d5-reto-4"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:4.1.1"],"prompt":"Completa con la palabra cuya r inicial suena fuerte.","type":"fill-blank","props":{"text":"La palabra es [[rábano]].","distractors":["pera","arena"]},"id":"s06-d5-reto-5"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:3.3.1"],"prompt":"A new card says: “First, wash the cup. Then, add the fruit. Finally, serve it.” What happens immediately before serving?","type":"choice","props":{"options":[{"id":"a","text":"Add the fruit"},{"id":"b","text":"Wash the cup"},{"id":"c","text":"Store the card"}],"correct":["a"]},"id":"s06-d5-reto-6"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:4.2.1"],"prompt":"Un grupo se burla cada semana de la refacción de Joel y lo excluye. ¿Qué respuesta ayuda a detener el acoso?","type":"choice","props":{"options":[{"id":"a","text":"Acompañarlo, no repetir la burla y pedir apoyo adulto"},{"id":"b","text":"Decirle que cambie su comida para encajar"},{"id":"c","text":"Grabar la escena y compartirla"}],"correct":["a"]},"id":"s06-d5-reto-7"},{"fase":"comprobar","areas":["art"],"cnb":["art:3.2.4"],"prompt":"Relaciona la intención visual con la trama.","type":"match","props":{"pairs":[{"id":"a","left":"Sombra densa en una canasta","right":"Líneas cruzadas cercanas"},{"id":"b","left":"Zona clara de una servilleta","right":"Puntos separados"},{"id":"c","left":"Fibra curva de una hoja","right":"Líneas onduladas"}]},"id":"s06-d5-reto-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:2.1.17"],"prompt":"En una ejecución nueva, el pase interno sale a la derecha. ¿Qué ajuste conviene probar?","type":"choice","props":{"options":[{"id":"a","text":"Orientar el pie de apoyo hacia el objetivo y mantener firme el tobillo"},{"id":"b","text":"Cerrar los ojos al golpear"},{"id":"c","text":"Pisar encima del balón"}],"correct":["a"]},"id":"s06-d5-reto-9"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:4.1.1"],"prompt":"Un proyecto usa 5 carteles a Q3 y 2 marcadores a Q4. ¿Cuál es el presupuesto total?","type":"number-input","props":{"answer":23,"unit":"quetzales"},"id":"s06-d5-reto-10"}]}},{"missionId":"s06","version":"cnb-sexto-1031ff7339e6c722","lesson":{"id":"s06-mat-3","title":"Unión e intersección con diagramas de Venn","icon":"Combine","minutes":14,"gancho":"Dos grupos siembran árboles en el vivero escolar. ¿Qué especies sembraron entre los dos? ¿Cuáles sembraron ambos?","objetivos":["Resolver unión e intersección de conjuntos"],"resumen":["Un diagrama de Venn dibuja cada conjunto como un óvalo; los elementos comunes van en la parte donde los óvalos se cruzan.","Unión A ∪ B: todos los elementos que están en A, en B o en ambos, sin repetir.","Intersección A ∩ B: solo los elementos que están en A y también en B. Si no hay comunes, A ∩ B = ∅ (conjuntos disjuntos).","Con tres conjuntos, el centro del diagrama guarda los elementos que están en los tres."],"media":{"id":"s06-mat-3-vivero","kind":"image","title":"El vivero escolar","aspect":"4:3","alt":"Dos grupos de estudiantes en un vivero escolar con bolsitas de arbolitos; cada grupo tiene un rótulo con las especies que siembra.","brief":"Ilustración de un vivero escolar al aire libre en Guatemala: hileras de bolsitas negras con arbolitos. A la izquierda, el grupo de Ana con un rótulo \\"A: pino, aliso, aguacate\\"; a la derecha, el grupo de Luis con un rótulo \\"B: aguacate, jocote, aliso, ciprés\\". En el centro, una maestra señala un pizarrón con dos óvalos cruzados. Estudiantes diversos, colores verdes y tierra, estilo plano. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:3.2.1"],"ambito":"conocer","title":"Diagrama de Venn, unión e intersección","prompt":"Un **diagrama de Venn** dibuja cada conjunto como un óvalo. Los óvalos se cruzan si tienen elementos en común. Toca cada tarjeta.","media":{"id":"s06-mat-3-venn2","kind":"diagram","title":"Venn de dos conjuntos","aspect":"16:9","alt":"Dos óvalos cruzados, A y B. Solo en A: pino. En el cruce: aliso y aguacate. Solo en B: jocote y ciprés. Debajo, dos copias: una con todo sombreado (A ∪ B) y otra con solo el cruce sombreado (A ∩ B).","brief":"Diagrama con tres paneles. Panel grande arriba: rectángulo con dos óvalos cruzados, A (verde) y B (azul). Solo en A: \\"pino\\"; en el cruce: \\"aliso\\", \\"aguacate\\"; solo en B: \\"jocote\\", \\"ciprés\\". Abajo, dos paneles pequeños: el primero con ambos óvalos completamente sombreados y el rótulo \\"A ∪ B = {pino, aliso, aguacate, jocote, ciprés}\\"; el segundo con solo el cruce sombreado y el rótulo \\"A ∩ B = {aliso, aguacate}\\". Fondo blanco, letras grandes. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"Combine","body":"El **cruce** de los óvalos guarda los elementos que están en los dos conjuntos.","reveal":[{"icon":"Merge","front":"Unión A ∪ B","back":"Todos los elementos de A **o** de B, sin repetir. Se lee \\"A unión B\\". Es TODO lo sombreado."},{"icon":"SquaresIntersect","front":"Intersección A ∩ B","back":"Solo los elementos que están en A **y también** en B. Se lee \\"A intersección B\\". Es el cruce."},{"icon":"CircleOff","front":"Disjuntos","back":"Si dos conjuntos no tienen elementos comunes, sus óvalos no se cruzan y A ∩ B = ∅."},{"icon":"TriangleAlert","front":"Error frecuente","back":"En la unión, un elemento común se escribe **una sola vez**: aliso no va dos veces."}]},"id":"s06-mat-3-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: el vivero","prompt":"Así se llenan el diagrama y las operaciones.","type":"worked-example","props":{"icon":"Trees","problem":"A = {pino, aliso, aguacate} y B = {aguacate, jocote, aliso, ciprés}. Encuentra **A ∩ B** y **A ∪ B**.","steps":[{"text":"Busco los comunes: aliso y aguacate. Los escribo en el **cruce**.","why":"Siempre se empieza por el cruce."},{"text":"Lo que queda de A (pino) va en la parte \\"solo A\\". Lo que queda de B (jocote, ciprés) va en \\"solo B\\"."},{"text":"**A ∩ B = {aliso, aguacate}**."},{"text":"**A ∪ B = {pino, aliso, aguacate, jocote, ciprés}**: todo lo del diagrama, sin repetir."}],"answer":"A ∩ B tiene 2 elementos y A ∪ B tiene 5.","tip":"Comprueba: 3 elementos de A + 4 de B = 7, pero los 2 comunes se contaron dos veces: 7 − 2 = 5."},"id":"s06-mat-3-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.1"],"ambito":"conocer","prompt":"El grupo de Ana siembra A = {pino, aliso, aguacate}. El de Luis siembra B = {aguacate, jocote, aliso, ciprés}. ¿Qué especies siembran **los dos grupos**?","explain":"Aliso y aguacate están en las dos listas. Ese es el conjunto **intersección**. Hoy aprenderás a encontrarlo con un dibujo.","type":"choice","props":{"options":[{"id":"a","text":"Aliso y aguacate"},{"id":"b","text":"Pino y ciprés","feedback":"El pino solo lo siembra Ana y el ciprés solo Luis."},{"id":"c","text":"Todas las especies","feedback":"Eso sería juntar las dos listas. Busca las que se repiten."}],"correct":["a"]},"id":"s06-mat-3-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.1"],"prompt":"Otro grado tiene C = {encino, pino, café, limón} y D = {limón, café, matilisguate}. Coloca cada especie en su parte del diagrama de Venn.","hint":"Primero busca las que están en las dos listas: van al cruce.","explain":"Café y limón están en los dos conjuntos: C ∩ D = {café, limón}.","type":"sort","props":{"buckets":[{"id":"c","label":"Solo en C","icon":"CircleDot"},{"id":"cd","label":"En C y en D (cruce)","icon":"SquaresIntersect","color":"var(--c-maiz-strong)"},{"id":"d","label":"Solo en D","icon":"CircleDot"}],"items":[{"id":"a","text":"encino","bucket":"c"},{"id":"b","text":"pino","bucket":"c"},{"id":"e","text":"café","bucket":"cd"},{"id":"f","text":"limón","bucket":"cd"},{"id":"g","text":"matilisguate","bucket":"d"}]},"id":"s06-mat-3-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.1"],"prompt":"Con los mismos C = {encino, pino, café, limón} y D = {limón, café, matilisguate}: ¿cuántos elementos tiene **C ∪ D**?","hint":"Cuenta todo lo que colocaste en el diagrama, una sola vez.","explain":"C ∪ D = {encino, pino, café, limón, matilisguate}: 5 elementos.","type":"number-input","props":{"answer":5,"misconceptions":[{"value":7,"msg":"Contaste café y limón dos veces. En la unión, cada elemento va una sola vez."},{"value":2,"msg":"Ese es el número de elementos de la intersección. La unión los junta todos."}]},"id":"s06-mat-3-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.1"],"ambito":"conocer","title":"Tres conjuntos","prompt":"Con **tres** conjuntos, los óvalos se cruzan formando **7 partes**. Toca cada tarjeta. Usaremos A = {1, 2, 3, 4}, B = {3, 4, 5} y C = {4, 5, 6}.","media":{"id":"s06-mat-3-venn3","kind":"diagram","title":"Venn de tres conjuntos","aspect":"1:1","alt":"Tres óvalos cruzados A, B y C. Solo A: 1 y 2. A y B: 3. Centro (A, B y C): 4. B y C: 5. Solo C: 6.","brief":"Diagrama cuadrado con tres óvalos de colores (A rojo arriba a la izquierda, B azul arriba a la derecha, C amarillo abajo) que se cruzan formando 7 regiones. Números: 1 y 2 en \\"solo A\\"; 3 en \\"A y B, no C\\"; 4 en el centro de los tres; 5 en \\"B y C, no A\\"; 6 en \\"solo C\\". Las regiones vacías quedan en blanco. Una flecha señala el centro con el texto \\"A ∩ B ∩ C\\". Fondo blanco. Dimensiones: 1200x1200. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"CircleDashed","body":"Llena el diagrama **del centro hacia afuera**: primero lo que está en los tres, luego lo que está en dos, al final lo que está en uno solo.","reveal":[{"icon":"Target","front":"Centro: A ∩ B ∩ C","back":"El 4 está en los tres: A ∩ B ∩ C = {4}."},{"icon":"SquaresIntersect","front":"En dos conjuntos","back":"El 3 está en A y B (no en C). El 5 está en B y C (no en A)."},{"icon":"Merge","front":"Unión de los tres","back":"A ∪ B ∪ C = {1, 2, 3, 4, 5, 6}: todos, sin repetir."}]},"id":"s06-mat-3-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:3.2.1"],"prompt":"Resuelve la intersección. Supongamos estos clubes de la escuela:\\nFútbol F = {Ana, Luis, Rosa, Juan}\\nMarimba M = {Rosa, Pedro, Ana}\\nAjedrez J = {Juan, Rosa, Mía}\\n¿Quién está en **los tres** clubes (F ∩ M ∩ J)?","explain":"Solo Rosa aparece en las tres listas: F ∩ M ∩ J = {Rosa}.","type":"choice","props":{"options":[{"id":"a","text":"Ana","feedback":"Ana está en fútbol y marimba, pero no en ajedrez."},{"id":"b","text":"Rosa"},{"id":"c","text":"Juan","feedback":"Juan está en fútbol y ajedrez, pero no en marimba."}],"correct":["b"]},"id":"s06-mat-3-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:3.2.1"],"prompt":"Resuelve la unión. Con los mismos clubes F = {Ana, Luis, Rosa, Juan}, M = {Rosa, Pedro, Ana} y J = {Juan, Rosa, Mía}: ¿cuántos estudiantes distintos hay en **F ∪ M ∪ J**?","explain":"F ∪ M ∪ J = {Ana, Luis, Rosa, Juan, Pedro, Mía}: 6 estudiantes.","type":"number-input","props":{"answer":6,"misconceptions":[{"value":10,"msg":"Sumaste 4 + 3 + 3, pero algunos estudiantes están en más de un club. Cuenta a cada persona una sola vez."}]},"id":"s06-mat-3-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:3.2.1"],"prompt":"P = {2, 4, 6, 8} y Q = {1, 3, 5}. ¿Verdadero o falso?","explain":"P tiene pares y Q impares: no comparten ningún elemento.","type":"true-false","props":{"statements":[{"text":"P ∩ Q = ∅","answer":true},{"text":"P y Q son disjuntos.","answer":true},{"text":"P ∪ Q tiene 6 elementos.","answer":false,"why":"P ∪ Q = {1, 2, 3, 4, 5, 6, 8}: tiene 7 elementos."}]},"id":"s06-mat-3-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:3.2.1"],"prompt":"Resuelve la unión: R = {2, 4, 6, 8} y T = {3, 6, 9}. ¿Cuál es **R ∪ T**?","type":"choice","props":{"options":[{"id":"a","text":"{6}"},{"id":"b","text":"{2, 3, 4, 6, 8, 9}"},{"id":"c","text":"{2, 3, 4, 6, 6, 8, 9}"}],"correct":["b"]},"id":"s06-mat-3-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:3.2.1"],"prompt":"Resuelve la intersección: V = {a, e, i, o, u} y W = {a, b, c, d, e}. ¿Cuántos elementos tiene **V ∩ W**?","type":"number-input","props":{"answer":2},"id":"s06-mat-3-11"}],"kind":"materia","area":"mat","day":3}},{"missionId":"s06","version":"cnb-sexto-7417111b4c064753","lesson":{"id":"s06-l1-3","title":"El predicado: el verbo y lo que lo acompaña","icon":"Zap","minutes":13,"gancho":"\\"El niño corre.\\" Es una oración completa… pero ¿no te dan ganas de saber dónde, cuándo y por qué corre?","objetivos":["Reconocer el verbo como núcleo del predicado"],"resumen":["El predicado es todo lo que se dice del sujeto. Su núcleo es el verbo conjugado: siembra, corrían, está.","El predicado se amplía con palabras que responden a ¿qué?, ¿dónde?, ¿cuándo?, ¿cómo? o ¿para qué?","El sujeto también se amplía con palabras que dicen cómo es o de quién es (connotativas y no connotativas).","El verbo debe concordar con el sujeto: \\"Las raíces sostienen\\", \\"La raíz sostiene\\"."],"media":{"id":"s06-l1-3-ampliar","kind":"animation","title":"Una oración que crece","aspect":"16:9","duration":40,"alt":"La oración \\"El niño corre\\" crece con bloques de colores: \\"de la aldea\\", \\"por el camino de tierra\\", \\"cada mañana\\", \\"para llegar a la escuela\\".","brief":"Animación tipográfica de 40 s. Empieza con \\"El niño | corre.\\" (sujeto azul, predicado verde, verbo amarillo). Van entrando bloques con una etiqueta: \\"de la aldea\\" se pega al sujeto (¿cuál niño?); luego al predicado \\"por el camino de tierra\\" (¿dónde?), \\"cada mañana\\" (¿cuándo?), \\"con su mochila al hombro\\" (¿cómo?), \\"para llegar a la escuela\\" (¿para qué?). Al final se lee la oración completa. Narración en español, subtítulos."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"conocer","title":"El predicado y su núcleo","prompt":"El **predicado** es todo lo que se dice del sujeto. Toca cada tarjeta.","type":"explain","props":{"icon":"Zap","body":"Para encontrar el predicado: primero localiza el **sujeto**; todo lo demás es predicado.","reveal":[{"icon":"Target","front":"Núcleo: el verbo","back":"El núcleo del predicado es el **verbo conjugado**: la palabra que cambia con la persona y el tiempo (_siembro, siembras, sembraron, sembrará_)."},{"icon":"Plus","front":"Lo que lo acompaña","back":"Palabras que completan la acción y responden a: **¿qué?** (vende _café_), **¿dónde?** (_en Cobán_), **¿cuándo?** (_los sábados_), **¿cómo?** (_con alegría_), **¿para qué?** (_para ayudar a su familia_)."},{"icon":"Link","front":"Concordancia","back":"El verbo concuerda con el núcleo del sujeto: \\"**El** maíz **crece**\\", \\"**Los** maíces **crecen**\\"."}]},"id":"s06-l1-3-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","title":"Ejemplo resuelto: hacer crecer una oración","prompt":"Una oración mínima tiene sujeto y verbo. Mira cómo se enriquece sin perder claridad.","type":"worked-example","props":{"icon":"Sprout","problem":"Oración mínima: \\"**El niño corre.**\\"","steps":[{"text":"Amplío el **sujeto**: ¿cuál niño? → \\"El niño **de la aldea**\\"."},{"text":"Amplío el **predicado** con ¿dónde?: \\"corre **por el camino de tierra**\\"."},{"text":"Agrego ¿cuándo?: \\"**cada mañana**\\"."},{"text":"Agrego ¿para qué?: \\"**para llegar a tiempo a la escuela**\\".","why":"Cada bloque responde a una pregunta distinta: así la información no se repite."}],"answer":"\\"**El niño de la aldea** | **corre por el camino de tierra cada mañana para llegar a tiempo a la escuela.**\\"","tip":"No agregues bloques por agregar: cada uno debe decir algo que el lector necesita saber."},"id":"s06-l1-3-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"conocer","prompt":"Toca la palabra que dice **la acción** en cada oración.","explain":"Esas palabras son **verbos**: el corazón del predicado. Sin verbo, no hay predicado.","type":"highlight","props":{"target":"verbos","text":"El maíz {crece} alto. Mi tío {vende} café en Cobán. Las nubes {cubren} el volcán."},"id":"s06-l1-3-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","prompt":"Toca el **predicado completo** de cada oración (cada predicado es un solo bloque).","hint":"Primero encuentra el sujeto con la pregunta ¿quién? o ¿qué?; el resto es el predicado.","explain":"Predicados: \\"vende tamales los domingos\\", \\"llegó tarde por la lluvia\\" y \\"pintan un mural en la escuela\\".","type":"highlight","props":{"target":"predicados","text":"Doña Irma {vende tamales los domingos}. El bus de la aldea {llegó tarde por la lluvia}. Los jóvenes del pueblo {pintan un mural en la escuela}."},"id":"s06-l1-3-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","prompt":"Une cada parte del predicado con la pregunta que responde.","hint":"Haz la pregunta con el verbo: ¿dónde siembra?, ¿cuándo siembra?…","type":"match","props":{"leftTitle":"Parte del predicado","rightTitle":"Responde a…","pairs":[{"id":"q1","left":"Don Mario siembra **frijol**.","right":"¿Qué?"},{"id":"q2","left":"Don Mario siembra **en la ladera**.","right":"¿Dónde?"},{"id":"q3","left":"Don Mario siembra **en mayo**.","right":"¿Cuándo?"},{"id":"q4","left":"Don Mario siembra **con cuidado**.","right":"¿Cómo?"},{"id":"q5","left":"Don Mario siembra **para vender en el mercado**.","right":"¿Para qué?"}]},"id":"s06-l1-3-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","prompt":"Completa cada oración con el **verbo** que concuerda con su sujeto.","explain":"Los pinos (plural) → crecen. La raíz (singular) → absorbe. Mis abuelos (plural) → cuentan. El río (singular) → baja.","type":"fill-blank","props":{"text":"Los pinos [[crecen]] en la montaña. La raíz [[absorbe]] el agua del suelo. Mis abuelos [[cuentan]] historias por la noche. El río [[baja]] crecido en invierno.","distractors":["crece","absorben","cuenta","bajan"]},"id":"s06-l1-3-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","prompt":"Ordena los bloques para formar una oración bimembre con sentido: **sujeto** primero, después **verbo** y lo que lo acompaña.","explain":"\\"Las abejas del apiario | llevan el polen de flor en flor durante la mañana.\\"","type":"order","props":{"labels":{"start":"Inicio","end":"Final"},"items":[{"id":"b1","text":"Las abejas del apiario"},{"id":"b2","text":"llevan"},{"id":"b3","text":"el polen de flor en flor"},{"id":"b4","text":"durante la mañana."}]},"id":"s06-l1-3-7"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","prompt":"Haz crecer estas dos oraciones mínimas. Amplía el **sujeto** una vez y el **predicado** con al menos **dos** preguntas (¿qué?, ¿dónde?, ¿cuándo?, ¿cómo?, ¿para qué?).\\n\\n1. \\"La vecina teje.\\"\\n2. \\"Los árboles protegen.\\"","type":"short-answer","props":{"minWords":25,"placeholder":"1. …\\n2. …","model":"1. La vecina de la esquina teje una faja roja en su telar de cintura todas las tardes.\\n2. Los árboles del cerro protegen el nacimiento de agua durante la época seca.","rubric":["Amplié el sujeto de cada oración","Amplié el predicado con al menos dos preguntas distintas","El verbo concuerda con el sujeto","Las oraciones se entienden y no repiten información"]},"id":"s06-l1-3-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:7.2.6"],"prompt":"En \\"_La municipalidad y la escuela organizaron la feria_\\", ¿cuál es el **predicado**?","type":"choice","props":{"options":[{"id":"a","text":"organizaron la feria"},{"id":"b","text":"La municipalidad y la escuela"},{"id":"c","text":"la feria"}],"correct":["a"]},"id":"s06-l1-3-9"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:7.2.6"],"prompt":"Toca el **núcleo del predicado** (el verbo) de cada oración.","type":"highlight","props":{"target":"verbos","text":"Mi prima Lucía {estudia} en Quetzaltenango. Todos los lunes {limpiamos} el aula. El volcán de Fuego {lanza} ceniza."},"id":"s06-l1-3-10"}],"kind":"materia","area":"l1","day":3}},{"missionId":"s06","version":"cnb-sexto-927545b9294f28e8","lesson":{"id":"s06-cnt-2","title":"Ambiente sano y ambiente contaminado","icon":"ShieldCheck","minutes":13,"gancho":"Un lugar puede verse ordenado y aun tener agua, aire o suelo contaminados. ¿Qué evidencia permite distinguirlo?","objetivos":["Diferenciar ambientes sanos y contaminados mediante evidencia observable"],"resumen":["Un ambiente sano reduce exposiciones y maneja de forma segura agua, aire, suelo y residuos.","Un ambiente contaminado contiene agentes o residuos que pueden dañar seres vivos.","Una señal aislada orienta una revisión, pero la clasificación necesita evidencia suficiente."],"media":{"id":"s06-cnt-2-ambientes","kind":"diagram","title":"Dos ambientes para comparar","aspect":"16:9","alt":"Dos patios ficticios: uno con residuos contenidos, aire ventilado y agua protegida; otro con humo, aguas residuales y basura dispersa.","brief":"Diagrama comparativo 1600×900 de dos escenarios ficticios, rotulados A y B. Mostrar fuentes concretas de evidencia en agua, aire, suelo y residuos. Evitar indicar la respuesta solo con color; usar rótulos legibles, patrones y alto contraste."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:6.1.1"],"title":"Distinguir requiere evidencia","prompt":"Un ambiente sano y uno contaminado se diferencian por condiciones del agua, aire, suelo y manejo de residuos.","type":"explain","props":{"icon":"Search","body":"Ambiente **sano**: reduce exposiciones y protege recursos. Ambiente **contaminado**: presenta humo, aguas residuales, sustancias o residuos que pueden afectar seres vivos."},"id":"s06-cnt-2-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:6.1.1"],"title":"Cuatro campos de observación","prompt":"Compara agua, aire, suelo y residuos antes de clasificar.","type":"explain","props":{"icon":"TableProperties","body":"Pregunta: ¿hay una fuente de contaminación?, ¿qué recurso alcanza?, ¿qué evidencia se observa?, ¿qué dato faltaría confirmar? Un olor o color por sí solo no identifica siempre la sustancia."},"id":"s06-cnt-2-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:6.1.1"],"title":"Modelo: evidencia y clasificación","prompt":"Diferencia dos ambientes ficticios.","type":"worked-example","props":{"icon":"GitCompare","problem":"Patio A: agua cubierta y residuos en contenedores. Patio B: humo constante y agua residual descargada al suelo.","steps":[{"text":"A muestra prácticas que reducen exposición."},{"text":"B presenta fuentes observables de contaminación del aire y suelo."},{"text":"No afirmamos qué sustancia contiene el agua sin analizarla."}],"answer":"A reúne señales de ambiente sano; B, evidencia de ambiente contaminado."},"id":"s06-cnt-2-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Clasifica la evidencia de la lección.","hint":"Ubica la condición del recurso, no la apariencia general.","explain":"Manejo seguro apoya un ambiente sano; descargas, humo y residuos dispersos evidencian contaminación.","type":"sort","props":{"buckets":[{"id":"sano","label":"Ambiente sano","icon":"ShieldCheck","color":"var(--c-ok)"},{"id":"cont","label":"Ambiente contaminado","icon":"CloudFog","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Agua almacenada en recipiente limpio y cubierto","bucket":"sano"},{"id":"b","text":"Humo de quema entra al aula","bucket":"cont"},{"id":"c","text":"Residuos separados y contenidos","bucket":"sano"},{"id":"d","text":"Aguas residuales corren sobre el suelo","bucket":"cont"}]},"id":"s06-cnt-2-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Relaciona evidencia y recurso afectado.","hint":"Pregunta dónde se observa la exposición.","explain":"Nombrar el recurso evita clasificaciones vagas.","type":"match","props":{"pairs":[{"id":"a","left":"Quema con humo persistente","right":"Aire contaminado"},{"id":"b","left":"Descarga de aguas residuales","right":"Agua o suelo contaminado"},{"id":"c","left":"Residuos cerrados y retiro organizado","right":"Condición que apoya un ambiente sano"}]},"id":"s06-cnt-2-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Caso nuevo: un patio tiene residuos contenidos, pero recibe humo. ¿Cómo diferencias ambiente sano y contaminado con evidencia de aire y residuos?","type":"choice","props":{"options":[{"id":"a","text":"El manejo de residuos es favorable, pero el humo evidencia contaminación del aire"},{"id":"b","text":"Es totalmente sano porque está ordenado"},{"id":"c","text":"Es contaminado solo porque el suelo es oscuro"}],"correct":["a"]},"id":"s06-cnt-2-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Diferencia los ambientes C y D usando una evidencia de agua, aire, suelo o residuos y un límite de lo que no puede concluirse.","type":"short-answer","props":{"minWords":18,"placeholder":"C muestra... D muestra... No puede concluirse...","model":"C reduce exposición al contener residuos. D muestra contaminación por humo. Sin análisis no puede nombrarse una sustancia específica.","rubric":["Diferencié ambos ambientes","Usé evidencia concreta","Reconocí un límite"]},"id":"s06-cnt-2-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"¿Qué comparación distingue un ambiente sano de uno contaminado mediante evidencia de agua, aire, suelo o residuos?","type":"choice","props":{"options":[{"id":"a","text":"Agua protegida y residuos contenidos reducen exposición; humo y descargas muestran contaminación"},{"id":"b","text":"Un lugar bonito siempre es sano"},{"id":"c","text":"Todo olor demuestra la misma sustancia"}],"correct":["a"]},"id":"s06-cnt-2-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Diferencia ambiente sano y contaminado con evidencia de agua, aire, suelo o residuos.","type":"true-false","props":{"statements":[{"text":"Una descarga de agua residual al suelo es evidencia de contaminación.","answer":true},{"text":"Un rótulo limpio demuestra por sí solo que todo el ambiente es sano.","answer":false}]},"id":"s06-cnt-2-9"},{"fase":"reflexionar","areas":["cnt"],"cnb":["cnt:6.1.1"],"prompt":"Revisa tu clasificación.","type":"reflection","props":{"statements":["Usé evidencia observable","Diferencié recurso y apariencia","Evité afirmar una sustancia sin análisis"],"commitments":["Pediré verificación cuando la evidencia no alcance"]},"id":"s06-cnt-2-10"}],"kind":"materia","area":"cnt","day":3}},{"missionId":"s06","version":"cnb-sexto-641965a521634d50","lesson":{"id":"s06-l2-1","title":"La r suave y la r fuerte","icon":"AudioLines","minutes":14,"gancho":"\\"Pero\\" y \\"perro\\" se parecen muchísimo… pero uno es una palabra que une ideas y el otro ¡ladra! ¿Qué las hace diferentes al oído?","objetivos":["Relacionar la escritura y posición de r o rr con el sonido suave o fuerte"],"resumen":["El español tiene dos sonidos de r: la r suave (la lengua toca una vez detrás de los dientes de arriba) y la r fuerte (la lengua vibra varias veces).","Suena fuerte: la rr entre vocales (perro), la r al inicio de palabra (rosa) y la r después de n, l o s (Enrique, alrededor, Israel).","Suena suave: la r entre vocales (pero), después de otra consonante en la misma sílaba (tres, grande) y al final de sílaba (mar, carta).","Cambiar el sonido cambia el significado: pero/perro, caro/carro, cero/cerro."],"media":{"id":"s06-l2-1-lengua","kind":"animation","title":"Cómo se mueve la lengua","aspect":"16:9","duration":40,"alt":"Corte lateral de la boca: en \\"pero\\" la lengua toca una vez detrás de los dientes de arriba; en \\"perro\\" vibra varias veces.","brief":"Animación 2D de 40 s con vista lateral simplificada de la boca (labios, dientes, paladar y lengua en colores suaves, sin realismo médico). Parte 1: se escucha \\"pero\\" y la punta de la lengua da UN toque rápido detrás de los dientes superiores; aparece el rótulo \\"r suave: 1 toque\\". Parte 2: se escucha \\"perro\\" y la lengua vibra 3-4 veces con líneas de movimiento; rótulo \\"r fuerte: vibra\\". Parte 3: se repite con \\"caro / carro\\" y \\"cero / cerro\\". Voz de adulto, pronunciación clara de español de Guatemala. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:4.1.1"],"ambito":"conocer","title":"Dos sonidos de r","prompt":"El español tiene **dos sonidos** de r. En muchos idiomas solo hay uno, por eso vale la pena practicarlos. Toca cada tarjeta y di las palabras en voz alta.","type":"explain","props":{"icon":"AudioLines","body":"Pon la punta de la lengua detrás de los dientes de arriba. La diferencia está en **cuántas veces** toca.","reveal":[{"icon":"Circle","front":"r suave","back":"La lengua **toca una sola vez**, rápido. Di: **pero, cara, loro, mar**."},{"icon":"AudioWaveform","front":"r fuerte","back":"La lengua **vibra varias veces**, como un motorcito. Di: **perro, carro, rosa, río**."},{"icon":"Lightbulb","front":"Truco para practicar","back":"Di rápido \\"**tra, tra, tra**\\" o \\"**dra, dra, dra**\\" y luego alarga el sonido: \\"trrrrr\\". Así la lengua aprende a vibrar."}]},"id":"s06-l2-1-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:4.1.1"],"ambito":"hacer","title":"Ejemplo resuelto: ¿fuerte o suave?","prompt":"Hay reglas para saber cuándo la r suena **fuerte**. Mira cómo se aplican a cuatro palabras.","type":"worked-example","props":{"icon":"ListChecks","problem":"¿La r de **rosa**, **carro**, **Enrique** y **pero** suena fuerte o suave?","steps":[{"text":"**rosa**: la r está **al inicio de la palabra** → fuerte.","why":"Al inicio de palabra siempre se escribe una sola r, pero suena fuerte."},{"text":"**carro**: hay **rr** entre dos vocales → fuerte.","why":"La rr solo aparece entre vocales y siempre suena fuerte."},{"text":"**Enrique**: la r va **después de n** → fuerte. Lo mismo pasa después de l (alrededor) y de s (Israel)."},{"text":"**pero**: una sola r **entre vocales** → suave."}],"answer":"Fuerte: **rosa, carro, Enrique**. Suave: **pero**.","tip":"Fuerte: al inicio, con rr, o después de n, l, s. En los demás casos, suave."},"id":"s06-l2-1-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:4.1.2"],"ambito":"conocer","prompt":"Escucha el audio. ¿Qué compró la abuela?","explain":"\\"Carro\\" (con r fuerte) es un vehículo; \\"caro\\" (con r suave) significa que cuesta mucho. Un solo sonido cambia la palabra. Hoy aprenderás a pronunciar y distinguir las dos r.","media":{"id":"s06-l2-1-carro","kind":"audio","title":"Caro o carro","duration":10,"alt":"Audio breve para identificar por el sonido lo que compró la abuela.","brief":"Mock MP3. Texto exacto: \\"Mi abuela compró un carro.\\" Voz adulta femenina, español de Guatemala, ritmo claro y pausado. Pronunciar la rr con vibración múltiple; repetir dos veces con 2 s de silencio. Duración: 10 s. La transcripción accesible se ofrece después de responder o mediante apoyo docente, sin mostrarla antes de la respuesta. Reemplazo: public/media/s06-l2-1-carro.mp3."},"type":"choice","props":{"options":[{"id":"a","text":"carro: un vehículo","icon":"Car"},{"id":"b","text":"Algo que costó mucho dinero","icon":"Coins","feedback":"Eso sería \\"caro\\", con r suave. Escucha: en \\"carro\\" la lengua vibra varias veces."}],"correct":["a"]},"id":"s06-l2-1-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:4.1.1"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: di cada palabra en voz alta y clasifícala según el sonido de su r.","hint":"Revisa la regla: ¿está al inicio?, ¿es rr?, ¿va después de n, l o s? Si no, es suave.","explain":"Fuerte: ratón (inicio), tierra (rr), honra (después de n). Suave: cara, tres, flor.","type":"sort","props":{"buckets":[{"id":"f","label":"r fuerte","icon":"AudioWaveform","color":"var(--c-maiz-strong)"},{"id":"s","label":"r suave","icon":"Circle","color":"var(--area-l2)"}],"items":[{"id":"w1","text":"ratón","bucket":"f"},{"id":"w2","text":"cara","bucket":"s"},{"id":"w3","text":"tierra","bucket":"f"},{"id":"w4","text":"tres","bucket":"s","feedback":"La r va después de t en la misma sílaba (tres): suena suave."},{"id":"w5","text":"honra","bucket":"f","feedback":"Después de n la r suena fuerte, aunque se escribe una sola."},{"id":"w6","text":"flor","bucket":"s"}]},"id":"s06-l2-1-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:4.1.1"],"ambito":"hacer","prompt":"Escucha la oración y toca las palabras que tienen **r fuerte**.","hint":"Son 5. Busca rr, r al inicio de palabra y r después de n.","explain":"Rubén (inicio), perro (rr), corre (rr), cerro (rr) y Enrique (después de n) tienen r fuerte. \\"Por\\" y \\"para\\" tienen r suave.","media":{"id":"s06-l2-1-oracion","kind":"audio","title":"Oración con muchas r","duration":12,"alt":"Una voz lee: \\"El perro de Rubén corre por el cerro para buscar a Enrique.\\"","brief":"Audio de 12 s. Voz adulta masculina, pausada, español de Guatemala. Texto exacto: \\"El perro de Rubén corre por el cerro para buscar a Enrique.\\" Marcar con claridad la vibración de cada r fuerte y el toque simple de \\"por\\" y \\"para\\". Leer dos veces."},"type":"highlight","props":{"target":"palabras con r fuerte","text":"El {perro} de {Rubén} {corre} por el {cerro} para buscar a {Enrique}."},"id":"s06-l2-1-5"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:4.1.1"],"ambito":"hacer","prompt":"Sin pistas, une la **escritura y posición** de la r o rr con su **sonido suave o fuerte**.","type":"match","props":{"leftTitle":"Escritura y posición","rightTitle":"Sonido","pairs":[{"id":"p1","left":"r al inicio: ratón","right":"r fuerte"},{"id":"p2","left":"rr entre vocales: perro","right":"r fuerte"},{"id":"p3","left":"r después de n: honra","right":"r fuerte"},{"id":"p4","left":"r entre vocales: caro","right":"r suave"},{"id":"p5","left":"r al final: mar","right":"r suave"}]},"id":"s06-l2-1-6"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:4.1.1"],"ambito":"hacer","prompt":"Completa la regla visual que relaciona **posición**, **escritura** y sonido **suave o fuerte**.","type":"fill-blank","props":{"text":"Entre vocales, el sonido fuerte se escribe [[rr]], como en perro; al inicio se escribe [[r]], como en rosa. Una r entre vocales suele sonar [[suave]], como en pero.","distractors":["fuerte"]},"id":"s06-l2-1-7"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:4.1.1"],"ambito":"hacer","prompt":"Practica con **trabalenguas** tradicionales. Lee cada tarjeta en voz alta, primero despacio y luego más rápido. Voltéala para ver el consejo.","type":"flashcards","props":{"cards":[{"icon":"Car","front":"Erre con erre cigarro, erre con erre barril, rápido ruedan los carros cargados de azúcar del ferrocarril.","back":"Marca la vibración en **erre, cigarro, barril, rápido, ruedan, carros, ferrocarril**. La r de **cargados** es suave."},{"icon":"Dog","front":"El perro de Rosa y Roque no tiene rabo, porque Ramón Ramírez se lo ha cortado.","back":"**Rosa, Roque, rabo, Ramón, Ramírez**: r al inicio = fuerte. **Perro**: rr = fuerte. **Porque, cortado**: suave."},{"icon":"Mountain","front":"Pero el perro subió al cerro, y en el cerro el perro corrió.","back":"Alterna suave (**pero**) y fuerte (**perro, cerro, corrió**). Exagera la diferencia."}]},"id":"s06-l2-1-8"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:4.1.1"],"prompt":"Boleto de salida: ¿cuál palabra cumple la relación **una r entre vocales → sonido suave**?","type":"choice","props":{"options":[{"id":"a","text":"loro"},{"id":"b","text":"ropa"},{"id":"c","text":"burro"},{"id":"d","text":"Enrique"}],"correct":["a"]},"id":"s06-l2-1-9"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:4.1.1"],"prompt":"Relaciona la escritura y posición de r o rr con su sonido suave o fuerte.","type":"true-false","props":{"statements":[{"text":"La r al inicio de una palabra, como en \\"río\\", suena fuerte.","answer":true},{"text":"En \\"alrededor\\", la r después de l suena suave.","answer":false,"why":"Después de n, l o s, la r suena fuerte."},{"text":"\\"Cero\\" y \\"cerro\\" significan lo mismo.","answer":false,"why":"\\"Cero\\" es el número 0 y \\"cerro\\" es una montaña pequeña."}]},"id":"s06-l2-1-10"}],"kind":"materia","area":"l2","day":2}},{"missionId":"s06","version":"cnb-sexto-9bbb5cf529360932","lesson":{"id":"s06-ef-2","title":"Preparado y en calma: vestuario, respiración y relajación","icon":"Wind","minutes":15,"gancho":"¿Has intentado correr con zapatos de vestir o con los cordones sueltos? ¿Y te ha pasado que antes de un partido o un examen el corazón te late muy rápido?","objetivos":["Aplicar preparación y recuperación seguras en la actividad física"],"resumen":["Vestuario para la actividad física: ropa cómoda y fresca que deje mover el cuerpo, calzado deportivo con suela antideslizante y bien amarrado, cabello recogido y sin aretes, collares ni objetos en los bolsillos.","Según el lugar y el clima: al sol, gorra o sombrero y bloqueador; al frío, varias capas que te puedas quitar; en el monte, pantalón largo, manga larga y botas o zapatos cerrados.","Respiración abdominal lenta: inhala por la nariz inflando el abdomen (4 tiempos) y exhala despacio por la boca (4 a 6 tiempos). Calma el cuerpo y las emociones.","Relajación de tensión y soltura: aprieta un grupo de músculos 5 segundos y suéltalo 10 segundos, notando la diferencia. Ayuda después del ejercicio y en momentos de nervios o enojo."],"media":{"id":"s06-ef-2-respiracion","kind":"animation","title":"Respira como un globo","aspect":"16:9","duration":60,"alt":"Una niña acostada con un peluche sobre el abdomen: al inhalar el peluche sube como un globo que se infla; al exhalar despacio, baja. Un contador marca 4 tiempos para inhalar y 6 para exhalar.","brief":"Animación 2D tranquila de 60 s, colores suaves. (1) Una niña acostada boca arriba en un petate con un peluche sobre el abdomen. (2) Un globo dibujado dentro del abdomen se infla al inhalar por la nariz (contador 1-2-3-4) y se desinfla al exhalar por la boca (contador 1-2-3-4-5-6); el peluche sube y baja. (3) Un corazón en una esquina late rápido al inicio y más lento al final (sin cifras). (4) Texto final: \\"Inhala 4 · Exhala 6\\". Voz narradora calmada en español, subtítulos. Música ambiental muy suave."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"conocer","title":"El vestuario adecuado","prompt":"La ropa correcta depende de **qué actividad** harás, **dónde** y con **qué clima**. Mira la ilustración y toca cada tarjeta.","media":{"id":"s06-ef-2-vestuario","kind":"image","title":"Vestidos para cada actividad","aspect":"16:9","alt":"Tres niñas y niños vestidos para distintas actividades: uno para la cancha al sol con gorra, camiseta holgada y tenis; otra para una mañana fría con capas; otro para una siembra en el monte con pantalón largo, manga larga, sombrero y botas.","brief":"Ilustración en tres paneles con fondo guatemalteco: (1) cancha escolar al sol: gorra, camiseta clara holgada, pantaloneta, tenis amarrados, pachón de agua; (2) mañana fría en el altiplano: camiseta, suéter y chumpa en capas, pants y tenis; (3) jornada de siembra en el monte: sombrero, camisa manga larga, pantalón largo, botas de hule, bloqueador. Un pequeño recuadro tachado con chancletas, collar y zapatos de vestir. Sin marcas visibles en la ropa. Diversidad de pueblos y géneros. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"Shirt","body":"Regla general: **cómodo, seguro y apropiado al clima**. No hace falta ropa cara: basta con que cumpla su función.","reveal":[{"icon":"Shirt","front":"Ropa","back":"**Cómoda y holgada**, de tela que deje pasar el aire (como el algodón). Que no apriete ni se enrede."},{"icon":"Footprints","front":"Calzado","back":"**Tenis o zapatos deportivos** con suela que no resbale, **bien amarrados**. Nada de chancletas ni zapatos de vestir."},{"icon":"Sun","front":"Sol y calor","back":"Gorra o sombrero, **bloqueador** y ropa de colores claros. Lleva **agua**."},{"icon":"Snowflake","front":"Frío","back":"Varias **capas** (camiseta, suéter, chumpa) que te puedas quitar al entrar en calor y volver a poner al terminar."},{"icon":"TreePine","front":"Monte o siembra","back":"**Pantalón largo**, **manga larga** y zapatos cerrados o botas: te protegen de espinas, piedras e insectos."},{"icon":"Gem","front":"Sin accesorios","back":"Quítate **aretes, collares, relojes** y saca objetos de los bolsillos. Recoge el cabello largo. Evitas golpes y rasguños."}]},"id":"s06-ef-2-1"},{"fase":"construir","areas":["ef","cnt"],"cnb":["ef:3.1.2"],"ambito":"ser","title":"La respiración que calma","prompt":"Cuando haces ejercicio o sientes nervios, respiras rápido y el corazón se acelera. Puedes **ayudar a tu cuerpo a calmarse** con la respiración. Mira la animación y toca cada tarjeta.","type":"explain","props":{"icon":"Wind","body":"La respiración **abdominal lenta** usa el **diafragma**, un músculo debajo de los pulmones. Al respirar despacio y profundo, el cuerpo recibe la señal de que puede calmarse.","reveal":[{"icon":"Wind","front":"Inhala","back":"Por la **nariz**, contando **4**, inflando el **abdomen** como un globo (los hombros no suben)."},{"icon":"Hourglass","front":"Exhala","back":"Por la **boca**, despacio, contando **4 a 6**, desinflando el globo. Exhalar más largo que inhalar ayuda a calmarse."},{"icon":"Repeat","front":"Repite","back":"Haz de **5 a 10** respiraciones. Puedes hacerlo sentado, de pie o acostado."},{"icon":"Heart","front":"¿Cuándo?","back":"Después del ejercicio, antes de un partido o una prueba, cuando sientes enojo o miedo. Es tu herramienta para el **equilibrio emocional**."}]},"id":"s06-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:3.1.2"],"ambito":"ser","title":"Ejemplo resuelto: la relajación de tensión y soltura","prompt":"Otra técnica: **tensar y soltar** los músculos. Mira cómo la usa Tomás después de un partido en el que se enojó.","type":"worked-example","props":{"icon":"Smile","problem":"Tomás perdió un partido y siente los hombros duros, los puños apretados y la respiración agitada.","steps":[{"text":"Se sienta cómodo en un lugar tranquilo y hace **3 respiraciones abdominales** lentas."},{"text":"**Manos:** aprieta los puños fuerte **5 segundos**… y los **suelta 10 segundos**, notando cómo se aflojan.","why":"Al sentir la diferencia entre tensión y soltura, el cuerpo aprende a relajarse."},{"text":"**Hombros:** los sube hacia las orejas 5 segundos… y los deja caer 10 segundos."},{"text":"**Cara:** arruga la cara 5 segundos… y la afloja 10 segundos."},{"text":"Termina con 3 respiraciones más y nota cómo se siente: más tranquilo y listo para hablar de lo que pasó."}],"answer":"Tensar **5 s** y soltar **10 s** cada grupo de músculos, con respiraciones lentas al inicio y al final, ayuda a recuperar la calma.","tip":"Aprieta con fuerza, pero sin dolor. Si algo duele, no lo tenses tanto."},"id":"s06-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"conocer","prompt":"Mañana hay clase de Educación Física en la cancha, a pleno sol. ¿Qué te pondrías?","explain":"Ropa **cómoda y fresca**, **tenis bien amarrados** y **gorra**. El vestuario adecuado te protege y te deja moverte con libertad.","type":"choice","props":{"options":[{"id":"a","text":"Ropa cómoda y fresca, tenis bien amarrados y gorra","icon":"Shirt"},{"id":"b","text":"Pantalón de vestir, zapatos lustrados y reloj","icon":"Briefcase","feedback":"Esa ropa limita el movimiento y los zapatos de vestir resbalan."},{"id":"c","text":"Chancletas para ir más fresco","icon":"Footprints","feedback":"Las chancletas se salen y no protegen los pies: aumentan el riesgo de golpes y torceduras."}],"correct":["a"]},"id":"s06-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"conocer","prompt":"Clasifica cada prenda o accesorio para una clase de Educación Física en la cancha.","hint":"Piensa: ¿me deja mover?, ¿me protege?, ¿puede golpearme o hacerme caer?","explain":"Lo adecuado es cómodo, seguro y según el clima. Los accesorios y el calzado inadecuado pueden causar lesiones.","type":"sort","props":{"buckets":[{"id":"si","label":"Adecuado","icon":"Check","color":"var(--c-ok)"},{"id":"no","label":"No adecuado","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"v1","text":"Tenis bien amarrados","bucket":"si"},{"id":"v2","text":"Collar largo","bucket":"no"},{"id":"v3","text":"Camiseta de algodón holgada","bucket":"si"},{"id":"v4","text":"Chancletas","bucket":"no"},{"id":"v5","text":"Gorra y bloqueador en día de sol","bucket":"si"},{"id":"v6","text":"Pantalón de vestir ajustado","bucket":"no"}]},"id":"s06-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:3.1.2"],"ambito":"ser","prompt":"¡Mide cómo te calmas! **Parte 1:** mide tu pulso en reposo. **Parte 2:** haz 1 minuto de actividad intensa (trote en tu lugar con rodillas arriba y saltos suaves) y mide tu pulso. **Parte 3:** siéntate y haz respiración abdominal (inhala 4, exhala 6) y la relajación de tensión y soltura de manos, hombros y cara; mide otra vez. Observa cómo tu pulso baja. **Poco espacio:** todo en tu lugar. **Adaptación:** la actividad intensa puede ser con los brazos, sentado.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de la actividad intensa","exercise":{"name":"Trote con rodillas arriba y saltos suaves","icon":"Activity","seconds":60}},{"label":"Después de respirar y relajarte","exercise":{"name":"Respiración 4-6 y tensión-soltura","icon":"Wind","seconds":90}}]},"id":"s06-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"hacer","prompt":"Como preparación para la actividad física del sábado hay una **jornada de siembra** en la montaña: habrá sol, tierra, espinas y piedras. ¿Qué vestuario es adecuado? **Elige todas las correctas.**","explain":"En el monte hay que proteger la piel y los pies: manga y pantalón largos, zapatos cerrados, sombrero y bloqueador. Las chancletas y los shorts dejan la piel expuesta a espinas e insectos.","type":"choice","props":{"multiple":true,"options":[{"id":"a","text":"Pantalón largo y camisa de manga larga"},{"id":"b","text":"Botas o zapatos cerrados"},{"id":"c","text":"Sombrero o gorra y bloqueador"},{"id":"d","text":"Chancletas y short","feedback":"Dejan los pies y las piernas expuestos a espinas, piedras e insectos."}],"correct":["a","b","c"]},"id":"s06-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:3.1.2"],"ambito":"ser","prompt":"Como recuperación emocional antes de volver a la actividad física, ¿qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Heart","text":"Faltan 5 minutos para la final del torneo de pases. **Ana** siente el corazón acelerado, las manos sudadas y dice: \\"Mejor no juego, me voy a equivocar\\"."},"options":[{"id":"a","icon":"X","text":"Decirle: \\"Si tienes miedo, mejor quédate afuera\\"","consequence":"Ana se pierde la final y se queda con la idea de que los nervios no se pueden manejar.","values":["Evitar"],"constructive":false},{"id":"b","icon":"Wind","text":"Invitarla a hacer juntas 5 respiraciones abdominales y a soltar hombros y manos","consequence":"Ana se calma un poco, siente apoyo y decide jugar. Los nervios no desaparecen del todo, pero ya no la controlan.","values":["Empatía","Autocontrol","Compañerismo"],"constructive":true},{"id":"c","icon":"MessageCircle","text":"Recordarle que equivocarse es parte de aprender y que el equipo la apoya","consequence":"Ana se siente acompañada. Con palabras de apoyo y respiración, la confianza crece.","values":["Apoyo","Respeto"],"constructive":true}]},"id":"s06-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:3.1.2"],"prompt":"Durante la recuperación de la actividad física, en la respiración abdominal lenta, ¿qué parte del cuerpo se infla al inhalar?","type":"choice","props":{"options":[{"id":"a","text":"El abdomen"},{"id":"b","text":"Los hombros, que suben hasta las orejas"},{"id":"c","text":"Las mejillas"}],"correct":["a"]},"id":"s06-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:3.1.6","ef:3.1.2"],"prompt":"Sobre preparación y recuperación para la actividad física, ¿verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Para hacer ejercicio conviene quitarse aretes, collares y relojes.","answer":true},{"text":"Con frío es mejor usar varias capas de ropa que te puedas quitar.","answer":true},{"text":"En la relajación de tensión y soltura se aprieta el músculo hasta que duela.","answer":false,"why":"Se aprieta con fuerza pero sin dolor, y luego se suelta."},{"text":"Exhalar despacio y más largo que la inhalación ayuda a calmarse.","answer":true}]},"id":"s06-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["ef"],"cnb":["ef:3.1.2"],"type":"reflection","props":{"statements":["Paso el balón con la parte interna y externa de cada pie","Elijo el vestuario adecuado para cada actividad","Uso la respiración y la relajación para calmarme"],"commitments":["Revisaré mi ropa y mis cordones antes de cada clase","Practicaré 5 respiraciones lentas antes de dormir","Usaré la respiración cuando sienta nervios o enojo"]},"id":"s06-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s06","version":"cnb-sexto-f83362e308b494e6","lesson":{"id":"s06-l1-3","title":"El predicado: el verbo y lo que lo acompaña","icon":"Zap","minutes":13,"gancho":"\\"El niño corre.\\" Es una oración completa… pero ¿no te dan ganas de saber dónde, cuándo y por qué corre?","objetivos":["Reconocer el verbo como núcleo del predicado"],"resumen":["El predicado es todo lo que se dice del sujeto. Su núcleo es el verbo conjugado: siembra, corrían, está.","El predicado se amplía con palabras que responden a ¿qué?, ¿dónde?, ¿cuándo?, ¿cómo? o ¿para qué?","El sujeto también se amplía con palabras que dicen cómo es o de quién es (connotativas y no connotativas).","El verbo debe concordar con el sujeto: \\"Las raíces sostienen\\", \\"La raíz sostiene\\"."],"media":{"id":"s06-l1-3-ampliar","kind":"animation","title":"Una oración que crece","aspect":"16:9","duration":40,"alt":"La oración \\"El niño corre\\" crece con bloques de colores: \\"de la aldea\\", \\"por el camino de tierra\\", \\"cada mañana\\", \\"para llegar a la escuela\\".","brief":"Animación tipográfica de 40 s. Empieza con \\"El niño | corre.\\" (sujeto azul, predicado verde, verbo amarillo). Van entrando bloques con una etiqueta: \\"de la aldea\\" se pega al sujeto (¿cuál niño?); luego al predicado \\"por el camino de tierra\\" (¿dónde?), \\"cada mañana\\" (¿cuándo?), \\"con su mochila al hombro\\" (¿cómo?), \\"para llegar a la escuela\\" (¿para qué?). Al final se lee la oración completa. Narración en español, subtítulos."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"conocer","title":"El predicado y su núcleo","prompt":"El **predicado** es todo lo que se dice del sujeto. Toca cada tarjeta.","type":"explain","props":{"icon":"Zap","body":"Para encontrar el predicado: primero localiza el **sujeto**; todo lo demás es predicado.","reveal":[{"icon":"Target","front":"Núcleo: el verbo","back":"El núcleo del predicado es el **verbo conjugado**: la palabra que cambia con la persona y el tiempo (_siembro, siembras, sembraron, sembrará_)."},{"icon":"Plus","front":"Lo que lo acompaña","back":"Palabras que completan la acción y responden a: **¿qué?** (vende _café_), **¿dónde?** (_en Cobán_), **¿cuándo?** (_los sábados_), **¿cómo?** (_con alegría_), **¿para qué?** (_para ayudar a su familia_)."},{"icon":"Link","front":"Concordancia","back":"El verbo concuerda con el núcleo del sujeto: \\"**El** maíz **crece**\\", \\"**Los** maíces **crecen**\\"."}]},"id":"s06-l1-3-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","title":"Ejemplo resuelto: hacer crecer una oración","prompt":"Una oración mínima tiene sujeto y verbo. Mira cómo se enriquece sin perder claridad.","type":"worked-example","props":{"icon":"Sprout","problem":"Oración mínima: \\"**El niño corre.**\\"","steps":[{"text":"Amplío el **sujeto**: ¿cuál niño? → \\"El niño **de la aldea**\\"."},{"text":"Amplío el **predicado** con ¿dónde?: \\"corre **por el camino de tierra**\\"."},{"text":"Agrego ¿cuándo?: \\"**cada mañana**\\"."},{"text":"Agrego ¿para qué?: \\"**para llegar a tiempo a la escuela**\\".","why":"Cada bloque responde a una pregunta distinta: así la información no se repite."}],"answer":"\\"**El niño de la aldea** | **corre por el camino de tierra cada mañana para llegar a tiempo a la escuela.**\\"","tip":"No agregues bloques por agregar: cada uno debe decir algo que el lector necesita saber."},"id":"s06-l1-3-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"conocer","prompt":"Toca la palabra que dice **la acción** en cada oración.","explain":"Esas palabras son **verbos**: el corazón del predicado. Sin verbo, no hay predicado.","type":"highlight","props":{"target":"verbos","text":"El maíz {crece} alto. Mi tío {vende} café en Cobán. Las nubes {cubren} el volcán."},"id":"s06-l1-3-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","prompt":"Toca el **predicado completo** de cada oración (cada predicado es un solo bloque).","hint":"Primero encuentra el sujeto con la pregunta ¿quién? o ¿qué?; el resto es el predicado.","explain":"Predicados: \\"vende tamales los domingos\\", \\"llegó tarde por la lluvia\\" y \\"pintan un mural en la escuela\\".","type":"highlight","props":{"target":"predicados","text":"Doña Irma {vende tamales los domingos}. El bus de la aldea {llegó tarde por la lluvia}. Los jóvenes del pueblo {pintan un mural en la escuela}."},"id":"s06-l1-3-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","prompt":"Une cada parte del predicado con la pregunta que responde.","hint":"Haz la pregunta con el verbo: ¿dónde siembra?, ¿cuándo siembra?…","type":"match","props":{"leftTitle":"Parte del predicado","rightTitle":"Responde a…","pairs":[{"id":"q1","left":"Don Mario siembra **frijol**.","right":"¿Qué?"},{"id":"q2","left":"Don Mario siembra **en la ladera**.","right":"¿Dónde?"},{"id":"q3","left":"Don Mario siembra **en mayo**.","right":"¿Cuándo?"},{"id":"q4","left":"Don Mario siembra **con cuidado**.","right":"¿Cómo?"},{"id":"q5","left":"Don Mario siembra **para vender en el mercado**.","right":"¿Para qué?"}]},"id":"s06-l1-3-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","prompt":"Completa cada oración con el **verbo** que concuerda con su sujeto.","explain":"Los pinos (plural) → crecen. La raíz (singular) → absorbe. Mis abuelos (plural) → cuentan. El río (singular) → baja.","type":"fill-blank","props":{"text":"Los pinos [[crecen]] en la montaña. La raíz [[absorbe]] el agua del suelo. Mis abuelos [[cuentan]] historias por la noche. El río [[baja]] crecido en invierno.","distractors":["crece","absorben","cuenta","bajan"]},"id":"s06-l1-3-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","prompt":"Ordena los bloques para formar una oración bimembre con sentido: **sujeto** primero, después **verbo** y lo que lo acompaña.","explain":"\\"Las abejas del apiario | llevan el polen de flor en flor durante la mañana.\\"","type":"order","props":{"labels":{"start":"Inicio","end":"Final"},"items":[{"id":"b1","text":"Las abejas del apiario"},{"id":"b2","text":"llevan"},{"id":"b3","text":"el polen de flor en flor durante la mañana."}]},"id":"s06-l1-3-7"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:7.2.6"],"ambito":"hacer","prompt":"Haz crecer estas dos oraciones mínimas. Amplía el **sujeto** una vez y el **predicado** con al menos **dos** preguntas (¿qué?, ¿dónde?, ¿cuándo?, ¿cómo?, ¿para qué?).\\n\\n1. \\"La vecina teje.\\"\\n2. \\"Los árboles protegen.\\"","type":"short-answer","props":{"minWords":25,"placeholder":"1. …\\n2. …","model":"1. La vecina de la esquina teje una faja roja en su telar de cintura todas las tardes.\\n2. Los árboles del cerro protegen el nacimiento de agua durante la época seca.","rubric":["Amplié el sujeto de cada oración","Amplié el predicado con al menos dos preguntas distintas","El verbo concuerda con el sujeto","Las oraciones se entienden y no repiten información"]},"id":"s06-l1-3-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:7.2.6"],"prompt":"En \\"_La municipalidad y la escuela organizaron la feria_\\", ¿cuál es el **predicado**?","type":"choice","props":{"options":[{"id":"a","text":"organizaron la feria"},{"id":"b","text":"La municipalidad y la escuela"},{"id":"c","text":"la feria"}],"correct":["a"]},"id":"s06-l1-3-9"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:7.2.6"],"prompt":"Toca el **núcleo del predicado** (el verbo) de cada oración.","type":"highlight","props":{"target":"verbos","text":"Mi prima Lucía {estudia} en Quetzaltenango. Todos los lunes {limpiamos} el aula. El volcán de Fuego {lanza} ceniza."},"id":"s06-l1-3-10"}],"kind":"materia","area":"l1","day":3}},{"missionId":"s06","version":"cnb-sexto-d9ecbd7ee3154cf5","lesson":{"id":"s06-mat-4","title":"Diferencia y diferencia simétrica","icon":"SquareSplitHorizontal","minutes":14,"gancho":"Ana y Luis comparan sus canastas de fruta. ¿Qué tiene Ana que Luis no tiene? ¿Y qué frutas tiene solo uno de los dos?","objetivos":["Resolver diferencias entre conjuntos"],"resumen":["Diferencia A − B: los elementos de A que NO están en B. En el Venn, es la parte \\"solo A\\".","A − B y B − A casi siempre son distintos: el orden importa.","Diferencia simétrica A Δ B: los elementos que están en uno solo de los dos conjuntos (no en ambos).","A Δ B = (A − B) ∪ (B − A). También: A Δ B = (A ∪ B) − (A ∩ B)."],"media":{"id":"s06-mat-4-canastas","kind":"image","title":"Dos canastas de fruta","aspect":"4:3","alt":"Ana y Luis sostienen canastas de fruta. La de Ana tiene mango, piña, banano y papaya; la de Luis tiene piña, papaya y naranja.","brief":"Ilustración en un mercado guatemalteco: una niña (Ana) y un niño (Luis) muestran sus canastas. Canasta de Ana: mango, piña, banano, papaya. Canasta de Luis: piña, papaya, naranja. Entre ambos, flotando, un diagrama de Venn sencillo con esas frutas dibujadas en sus regiones (piña y papaya en el cruce). Estilo plano, colores vivos, sin texto adicional. Dimensiones: 1200x900."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:3.2.1"],"ambito":"conocer","title":"La diferencia A − B","prompt":"La **diferencia A − B** (se lee \\"A menos B\\") es el conjunto de elementos que están en A pero **no** en B. Toca cada tarjeta.","type":"explain","props":{"icon":"Minus","body":"Al conjunto A se le \\"quitan\\" los elementos que comparte con B.","reveal":[{"icon":"CircleDot","front":"En el Venn","back":"A − B es la parte de A que **no** toca a B: la zona \\"solo A\\"."},{"icon":"ArrowRightLeft","front":"El orden importa","back":"Con las canastas: A − B = {mango, banano}, pero B − A = {naranja}. ¡Son distintos!"},{"icon":"Circle","front":"Puede quedar vacío","back":"Si todos los elementos de A están en B, entonces A − B = ∅."}]},"id":"s06-mat-4-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: A − B y B − A","prompt":"Observa cómo se calcula cada diferencia.","type":"worked-example","props":{"icon":"Minus","problem":"A = {1, 2, 3, 4, 5} y B = {4, 5, 6, 7}. Encuentra **A − B** y **B − A**.","steps":[{"text":"Comunes: 4 y 5. Esos se \\"quitan\\".","why":"La diferencia nunca incluye elementos comunes."},{"text":"A − B: de A quito 4 y 5 → **{1, 2, 3}**."},{"text":"B − A: de B quito 4 y 5 → **{6, 7}**."}],"answer":"A − B = {1, 2, 3} y B − A = {6, 7}.","tip":"Lee la operación en voz alta: \\"lo que está en A y no en B\\"."},"id":"s06-mat-4-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.1"],"ambito":"conocer","prompt":"Canasta de Ana: A = {mango, piña, banano, papaya}. Canasta de Luis: B = {piña, papaya, naranja}. ¿Qué frutas tiene Ana que Luis **no** tiene?","explain":"Mango y banano. A esto se le llama **diferencia**: A − B = {mango, banano}.","type":"choice","props":{"options":[{"id":"a","text":"Mango y banano"},{"id":"b","text":"Piña y papaya","feedback":"Esas las tienen los dos."},{"id":"c","text":"Naranja","feedback":"La naranja la tiene Luis, no Ana."}],"correct":["a"]},"id":"s06-mat-4-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.1"],"prompt":"J = {lunes, martes, miércoles} y K = {martes, jueves}. ¿Cuál es **J − K**?","hint":"Empieza con J y quítale lo que también está en K.","explain":"Martes está en los dos; se quita. J − K = {lunes, miércoles}.","type":"choice","props":{"options":[{"id":"a","text":"{lunes, miércoles}"},{"id":"b","text":"{jueves}","feedback":"Eso es K − J: lo que está en K y no en J."},{"id":"c","text":"{martes}","feedback":"Martes es el elemento común; la diferencia lo quita."}],"correct":["a"]},"id":"s06-mat-4-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.3"],"ambito":"conocer","title":"La diferencia simétrica A Δ B","prompt":"La **diferencia simétrica A Δ B** (se lee \\"A delta B\\") reúne los elementos que están en **uno solo** de los dos conjuntos. Toca cada tarjeta.","media":{"id":"s06-mat-4-delta","kind":"diagram","title":"Diferencia y diferencia simétrica","aspect":"16:9","alt":"Tres diagramas de Venn de A y B. En el primero, sombreada solo la parte de A que no toca B (A − B). En el segundo, solo la parte de B (B − A). En el tercero, ambas partes sombreadas y el cruce en blanco (A Δ B).","brief":"Tres diagramas de Venn iguales en fila, con óvalos A (verde) y B (azul). 1) Sombreada solo la zona \\"solo A\\", rótulo \\"A − B\\". 2) Sombreada solo la zona \\"solo B\\", rótulo \\"B − A\\". 3) Sombreadas las zonas \\"solo A\\" y \\"solo B\\", con el cruce en blanco, rótulo \\"A Δ B = (A − B) ∪ (B − A)\\". Letras grandes, fondo blanco. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"Triangle","body":"En el Venn, A Δ B es todo lo sombreado **menos el cruce**.","reveal":[{"icon":"Merge","front":"Primera forma","back":"A Δ B = (A − B) ∪ (B − A). Junta las dos diferencias."},{"icon":"Eraser","front":"Segunda forma","back":"A Δ B = (A ∪ B) − (A ∩ B). Toma la unión y bórrale los comunes."},{"icon":"Apple","front":"Con las canastas","back":"A Δ B = {mango, banano, naranja}: las frutas que tiene **solo uno** de los dos niños."},{"icon":"ArrowRightLeft","front":"¿Y el orden?","back":"Aquí no importa: A Δ B = B Δ A. Por eso se llama \\"simétrica\\"."}]},"id":"s06-mat-4-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.3"],"ambito":"hacer","title":"Ejemplo resuelto: el vivero","prompt":"Calculemos una diferencia simétrica paso a paso.","type":"worked-example","props":{"icon":"Trees","problem":"P = {pino, aliso, ciprés} y Q = {aliso, encino}. Encuentra **P Δ Q**.","steps":[{"text":"P − Q = {pino, ciprés}."},{"text":"Q − P = {encino}."},{"text":"Junto las dos: P Δ Q = **{pino, ciprés, encino}**.","why":"El aliso está en ambos, por eso queda fuera."}],"answer":"P Δ Q = {pino, ciprés, encino}.","tip":"Comprueba con la segunda forma: P ∪ Q = {pino, aliso, ciprés, encino}; le quito el común (aliso) y queda lo mismo."},"id":"s06-mat-4-6"},{"fase":"construir","areas":["mat"],"cnb":["mat:3.2.3"],"prompt":"G = {a, e, i, o, u} y H = {a, b, c, d, e}. ¿Cuántos elementos tiene **G Δ H**?","hint":"Los comunes son a y e. Quédate con todo lo demás de los dos conjuntos.","explain":"G − H = {i, o, u} y H − G = {b, c, d}. G Δ H = {i, o, u, b, c, d}: 6 elementos.","type":"number-input","props":{"answer":6,"misconceptions":[{"value":3,"msg":"Contaste solo una de las diferencias. La simétrica junta las dos."},{"value":2,"msg":"Esos son los elementos comunes: justo los que la diferencia simétrica deja fuera."},{"value":8,"msg":"Esa es la unión. Quita los elementos comunes (a y e)."}]},"id":"s06-mat-4-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:3.2.1"],"prompt":"A = {2, 4, 6, 8, 10, 12} (pares hasta 12) y B = {3, 6, 9, 12} (múltiplos de 3 hasta 12). ¿Cuántos elementos tiene **A − B**?","explain":"Los comunes son 6 y 12. A − B = {2, 4, 8, 10}: 4 elementos.","type":"number-input","props":{"answer":4,"misconceptions":[{"value":2,"msg":"Ese es el número de elementos de B − A = {3, 9}. Aquí es A − B."},{"value":6,"msg":"Olvidaste quitar los elementos comunes (6 y 12)."}]},"id":"s06-mat-4-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:3.2.3"],"prompt":"Transfiere la **diferencia simétrica**. En una encuesta, a quienes les gusta el **atol de elote**: E = {Sara, Tito, Uriel, Vilma}. A quienes les gusta el **atol de plátano**: P = {Uriel, Vilma, Wendy}. ¿Cuál es **E Δ P**, las personas a quienes les gusta solo uno de los dos atoles?","explain":"Les gusta solo uno de los dos: E Δ P = {Sara, Tito, Wendy}. Uriel y Vilma disfrutan los dos.","type":"choice","props":{"options":[{"id":"a","text":"E ∩ P = {Uriel, Vilma}","feedback":"Esos son a quienes les gustan los dos."},{"id":"b","text":"E Δ P = {Sara, Tito, Wendy}"},{"id":"c","text":"E − P = {Sara, Tito}","feedback":"Te falta Wendy, a quien solo le gusta el de plátano."}],"correct":["b"]},"id":"s06-mat-4-9"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:3.2.1","mat:3.2.3"],"prompt":"M = {1, 2, 3} y N = {3, 4}. ¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"M − N = {1, 2}","answer":true},{"text":"N − M = {1, 2}","answer":false,"why":"N − M = {4}: lo que está en N y no en M."},{"text":"M Δ N = {1, 2, 4}","answer":true},{"text":"M Δ N = N Δ M","answer":true}]},"id":"s06-mat-4-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:3.2.1"],"prompt":"Resuelve la diferencia: C = {rojo, azul, verde, blanco} y D = {verde, negro, blanco}. ¿Cuál es **D − C**?","type":"fill-blank","props":{"text":"D − C = [[{negro}]].","distractors":["{rojo, azul}","{verde, blanco}"]},"id":"s06-mat-4-11"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:3.2.3"],"prompt":"Resuelve la diferencia simétrica con C = {rojo, azul, verde, blanco} y D = {verde, negro, blanco}: ¿cuál es **C Δ D**?","type":"choice","props":{"options":[{"id":"a","text":"{rojo, azul, negro}"},{"id":"b","text":"{verde, blanco}"},{"id":"c","text":"{rojo, azul, verde, blanco, negro}"}],"correct":["a"]},"id":"s06-mat-4-12"}],"kind":"materia","area":"mat","day":4}},{"missionId":"s06","version":"cnb-sexto-005b823b63192012","lesson":{"id":"s06-fc-2","title":"Cuando la violencia se repite: acoso y ciberacoso","icon":"ShieldCheck","minutes":15,"gancho":"Una pelea de un día y una burla que se repite todos los días durante meses, ¿son lo mismo?","objetivos":["Diferenciar un conflicto entre iguales del acoso escolar"],"resumen":["Un conflicto es un desacuerdo entre personas; se puede resolver hablando. El acoso escolar es violencia que se repite, a propósito, contra alguien que tiene menos poder para defenderse.","El ciberacoso es acoso por teléfono o internet: llega a cualquier hora, lo ven muchas personas y es difícil de borrar.","Si te pasa: no respondas con violencia, guarda la evidencia, bloquea o reporta y cuéntalo a un adulto de confianza. No es tu culpa.","Los testigos tienen mucho poder: no reírse, no reenviar, acompañar a quien sufre y avisar a un adulto."],"media":{"id":"s06-fc-2-testigos","kind":"animation","title":"El poder de los testigos","aspect":"16:9","duration":50,"alt":"Animación: un niño recibe burlas en el corredor mientras otros miran; uno a uno, los que miran dejan de reír, se acercan a acompañarlo y una niña va a buscar a la maestra.","brief":"Animación 2D de 50 s, trazos suaves. Corredor de una escuela guatemalteca. Un niño es rodeado por dos compañeros que se burlan; alrededor, seis testigos (niñas y niños de distintos pueblos) ríen y graban con un teléfono. Una voz explica: \\"La mayoría no agrede… pero mira\\". Una testigo baja el teléfono, otro deja de reír, dos se acercan al niño y le dicen \\"vení con nosotros\\"; una niña va por la maestra. Los agresores se quedan sin público. Cierre en texto: \\"Sin público, el acoso pierde fuerza\\". Sin golpes visibles; narración en español, subtítulos."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"conocer","title":"Conflicto no es lo mismo que acoso","prompt":"Los **conflictos** (desacuerdos) son normales entre personas y se pueden resolver hablando. El **acoso escolar** es distinto: tiene **tres señales**. Toca cada tarjeta.","type":"explain","props":{"icon":"ShieldCheck","body":"Si ves las tres señales juntas, no basta con \\"arreglarse entre ellos\\": se necesita la **ayuda de un adulto**.","reveal":[{"icon":"RefreshCw","front":"1. Se repite","back":"No es una vez: pasa **muchas veces**, durante semanas o meses."},{"icon":"Target","front":"2. Es a propósito","back":"Quien agrede **quiere** hacer daño, humillar o dar miedo. No es un accidente."},{"icon":"Scale","front":"3. Hay desigualdad de poder","back":"Quien sufre tiene **menos fuerza o apoyo**: es más pequeño, está solo, es nuevo o el grupo está en su contra."},{"icon":"MessagesSquare","front":"En cambio, un conflicto…","back":"Es un desacuerdo **entre iguales** (por un turno, un lápiz, una regla del juego) que se puede resolver con diálogo."}]},"id":"s06-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"conocer","title":"El ciberacoso","prompt":"El **ciberacoso** es acoso por **teléfono o internet**. Tiene sus propias características. Toca cada tarjeta.","type":"explain","props":{"icon":"Smartphone","body":"Detrás de cada pantalla hay una persona con sentimientos. Lo que publicas **se queda** y puede llegar a muchos.","reveal":[{"icon":"Clock","front":"Llega a cualquier hora","back":"No termina al salir de la escuela: sigue en la casa, de noche y los fines de semana."},{"icon":"Users","front":"Lo ven muchas personas","back":"Un mensaje o una foto se reenvía en segundos a decenas o cientos de personas."},{"icon":"Lock","front":"Es difícil de borrar","back":"Aunque se borre, alguien pudo **guardarlo**. Por eso nunca compartas fotos de otros sin permiso."},{"icon":"ShieldCheck","front":"Qué hacer si te pasa","back":"**No respondas** con insultos, **guarda la evidencia** (captura de pantalla), **bloquea o reporta** y **cuéntalo** a un adulto de confianza. No es tu culpa."}]},"id":"s06-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: el caso del chat","prompt":"Mira cómo Ana y un testigo, Luis, enfrentaron un caso de ciberacoso.","type":"worked-example","props":{"icon":"MessageCircle","problem":"En el chat del grado, alguien crea una encuesta: \\"¿Quién es la más fea del grado?\\" y pone la foto de Ana. Varios votan y mandan risas. Ana lo ve en la noche.","steps":[{"text":"Ana **no responde** con insultos, aunque siente mucha rabia y tristeza.","why":"Responder con violencia hace crecer el problema y puede meterla en problemas a ella."},{"text":"Ana **guarda la evidencia**: toma capturas de pantalla con la fecha."},{"text":"Ana **se sale del chat** y **se lo cuenta a su mamá** esa misma noche."},{"text":"Luis, que estaba en el chat, **no vota ni reenvía**; le escribe a Ana: \\"Eso está muy mal, cuenta conmigo\\", y avisa a la maestra.","why":"Un testigo que no se ríe y avisa le quita público al acoso."},{"text":"La mamá y la maestra hablan con la dirección; la escuela aplica sus **normas de convivencia** y habla con quienes participaron."}],"answer":"Ana se protegió y **pidió ayuda**; Luis usó su poder de **testigo**. Juntos, con los adultos, detuvieron el ciberacoso.","tip":"No respondo → guardo evidencia → bloqueo o reporto → se lo cuento a un adulto de confianza."},"id":"s06-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"convivir","prompt":"Desde hace tres meses, dos compañeros esconden la refacción de Pablo, que es el más pequeño del grado, y se ríen cuando él la busca. ¿Qué crees que es?","explain":"Es **acoso escolar**: se repite, es a propósito y Pablo tiene menos poder para defenderse. Hoy aprenderás a distinguirlo de un simple conflicto.","type":"choice","props":{"options":[{"id":"a","text":"Un juego sin importancia","icon":"Smile","feedback":"Un juego es divertido para todos. Aquí solo se ríen quienes esconden la refacción."},{"id":"b","text":"Algo más serio que se repite y hace daño","icon":"ShieldCheck"},{"id":"c","text":"Culpa de Pablo por ser pequeño","icon":"User","feedback":"Nunca es culpa de quien sufre la violencia."}],"correct":["b"]},"id":"s06-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:4.2.1"],"prompt":"Clasifica: ¿es un **conflicto** que se puede resolver hablando, o es **acoso** que necesita ayuda de un adulto?","hint":"Busca las tres señales: ¿se repite?, ¿es a propósito?, ¿uno tiene menos poder?","explain":"Los conflictos entre iguales se resuelven con diálogo. El acoso, con sus tres señales, necesita que intervenga un adulto.","type":"sort","props":{"buckets":[{"id":"con","label":"Conflicto","icon":"MessagesSquare","color":"var(--c-ok)"},{"id":"aco","label":"Acoso","icon":"ShieldCheck","color":"var(--c-bad)"}],"items":[{"id":"k1","text":"Dos amigas discuten un día porque las dos querían ser capitanas","bucket":"con"},{"id":"k2","text":"Un grupo de sexto le quita el dinero de la refacción a un niño de segundo cada semana","bucket":"aco"},{"id":"k3","text":"Dos equipos no se ponen de acuerdo sobre si fue gol","bucket":"con"},{"id":"k4","text":"Desde que llegó, a Lesbia le imitan su forma de hablar todos los días","bucket":"aco","feedback":"Se repite, es a propósito y ella es nueva: tiene las tres señales."},{"id":"k5","text":"Dos compañeros discuten por quién usa primero la computadora","bucket":"con"}]},"id":"s06-fc-2-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:4.2.1"],"prompt":"Ordena lo que conviene hacer si **te pasa** ciberacoso.","hint":"Primero te proteges sin empeorar las cosas; al final buscas ayuda con los adultos.","explain":"No responder → guardar evidencia → bloquear o reportar → contarlo a un adulto de confianza → buscar juntos apoyo en la escuela.","type":"order","props":{"labels":{"start":"Primero","end":"Después"},"items":[{"id":"c1","text":"No responder con insultos ni amenazas","icon":"VolumeX"},{"id":"c2","text":"Guardar la evidencia con capturas de pantalla","icon":"Camera"},{"id":"c3","text":"Bloquear o reportar a quien agrede","icon":"Lock"},{"id":"c4","text":"Contarlo a un adulto de confianza","icon":"MessageCircle"},{"id":"c5","text":"Buscar juntos el apoyo de la escuela","icon":"School"}]},"id":"s06-fc-2-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"convivir","prompt":"Eres testigo. ¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Smartphone","text":"Te llega un video donde se burlan de Walter, un compañero, porque se cayó en educación física. Te dicen: \\"¡Reenvialo a todos, está buenísimo!\\"."},"options":[{"id":"a","icon":"Share2","text":"Reenviarlo: total, ya lo vieron muchos","consequence":"El video llega a otros grados. Walter no quiere volver a la escuela. Tú fuiste parte de la cadena.","values":["Indiferencia"],"constructive":false},{"id":"b","icon":"VolumeX","text":"No reenviarlo y pedir en el chat que lo borren","consequence":"Algunos se molestan, pero otros te apoyan y el video se borra del chat. La cadena se corta contigo.","values":["Respeto","Valentía"],"constructive":true},{"id":"c","icon":"HeartHandshake","text":"No reenviarlo, escribirle a Walter para apoyarlo y avisar a la maestra","consequence":"Walter se siente acompañado. La maestra habla con el grado sobre el respeto en redes.","values":["Solidaridad","Responsabilidad"],"constructive":true}]},"id":"s06-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:4.2.1"],"ambito":"convivir","prompt":"Nidia sufre acoso y le da vergüenza contarlo. ¿Qué **adulto de confianza** puede ayudarla? Marca **todas** las opciones correctas.","explain":"Un adulto de confianza es alguien que te escucha, te cree y puede actuar: familia, docentes, dirección u orientación. Si hay peligro inmediato, se puede llamar a la **Policía Nacional Civil al 110**.","type":"choice","props":{"multiple":true,"options":[{"id":"a","text":"Su mamá, su papá o la persona que la cuida","icon":"Home"},{"id":"b","text":"Su maestra o la directora de la escuela","icon":"School"},{"id":"c","text":"Un desconocido que conoció en internet","icon":"Smartphone","feedback":"Un desconocido de internet no es un adulto de confianza. Busca personas que conoces y que te cuidan."},{"id":"d","text":"Una tía o un abuelo que la escucha","icon":"HeartHandshake"}],"correct":["a","b","d"]},"id":"s06-fc-2-8"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:4.2.1"],"prompt":"¿Cuál situación es **acoso escolar** y no un simple conflicto?","type":"choice","props":{"options":[{"id":"a","text":"Todos los días, un grupo le dice apodos a una niña nueva y no la deja entrar al salón"},{"id":"b","text":"Dos amigos discuten una vez sobre las reglas de un juego y luego se ponen de acuerdo"},{"id":"c","text":"Dos equipos no se ponen de acuerdo sobre la hora del partido"}],"correct":["a"]},"id":"s06-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:4.2.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Si sufres ciberacoso, conviene guardar la evidencia y contarlo a un adulto de confianza.","answer":true},{"text":"Los testigos no pueden hacer nada para detener el acoso.","answer":false,"why":"Los testigos pueden no reírse, no reenviar, acompañar a quien sufre y avisar a un adulto."},{"text":"El acoso escolar se repite, es a propósito y hay desigualdad de poder.","answer":true},{"text":"Si alguien sufre acoso, es porque se lo buscó.","answer":false,"why":"Nunca es culpa de quien sufre la violencia."}]},"id":"s06-fc-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["fc"],"cnb":["fc:4.2.1"],"type":"reflection","props":{"statements":["Reconozco la cultura de paz y la de violencia en mi casa, escuela y comunidad","Distingo un conflicto del acoso escolar","Sé qué hacer y a quién pedir ayuda ante el acoso y el ciberacoso"],"commitments":["No reenviaré nada que se burle de otra persona","Llamaré a mis compañeros por su nombre, no por apodos","Si veo acoso, acompañaré a quien lo sufre y avisaré a un adulto"]},"id":"s06-fc-2-11"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s06","version":"cnb-sexto-c58ee828c76a3fa8","lesson":{"id":"s06-ef-2","title":"Preparado y en calma: vestuario, respiración y relajación","icon":"Wind","minutes":15,"gancho":"¿Has intentado correr con zapatos de vestir o con los cordones sueltos? ¿Y te ha pasado que antes de un partido o un examen el corazón te late muy rápido?","objetivos":["Aplicar preparación y recuperación seguras en la actividad física"],"resumen":["Vestuario para la actividad física: ropa cómoda y fresca que deje mover el cuerpo, calzado deportivo con suela antideslizante y bien amarrado, cabello recogido y sin aretes, collares ni objetos en los bolsillos.","Según el lugar y el clima: al sol, gorra o sombrero y bloqueador; al frío, varias capas que te puedas quitar; en el monte, pantalón largo, manga larga y botas o zapatos cerrados.","Respiración abdominal lenta: inhala por la nariz inflando el abdomen (4 tiempos) y exhala despacio por la boca (4 a 6 tiempos). Calma el cuerpo y las emociones.","Relajación de tensión y soltura: aprieta un grupo de músculos 5 segundos y suéltalo 10 segundos, notando la diferencia. Ayuda después del ejercicio y en momentos de nervios o enojo."],"media":{"id":"s06-ef-2-respiracion","kind":"animation","title":"Respira como un globo","aspect":"16:9","duration":60,"alt":"Una niña acostada con un peluche sobre el abdomen: al inhalar el peluche sube como un globo que se infla; al exhalar despacio, baja. Un contador marca 4 tiempos para inhalar y 6 para exhalar.","brief":"Animación 2D tranquila de 60 s, colores suaves. (1) Una niña acostada boca arriba en un petate con un peluche sobre el abdomen. (2) Un globo dibujado dentro del abdomen se infla al inhalar por la nariz (contador 1-2-3-4) y se desinfla al exhalar por la boca (contador 1-2-3-4-5-6); el peluche sube y baja. (3) Un corazón en una esquina late rápido al inicio y más lento al final (sin cifras). (4) Texto final: \\"Inhala 4 · Exhala 6\\". Voz narradora calmada en español, subtítulos. Música ambiental muy suave."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"conocer","title":"El vestuario adecuado","prompt":"La ropa correcta depende de **qué actividad** harás, **dónde** y con **qué clima**. Mira la ilustración y toca cada tarjeta.","media":{"id":"s06-ef-2-vestuario","kind":"image","title":"Vestidos para cada actividad","aspect":"16:9","alt":"Tres niñas y niños vestidos para distintas actividades: uno para la cancha al sol con gorra, camiseta holgada y tenis; otra para una mañana fría con capas; otro para una siembra en el monte con pantalón largo, manga larga, sombrero y botas.","brief":"Ilustración en tres paneles con fondo guatemalteco: (1) cancha escolar al sol: gorra, camiseta clara holgada, pantaloneta, tenis amarrados, pachón de agua; (2) mañana fría en el altiplano: camiseta, suéter y chumpa en capas, pants y tenis; (3) jornada de siembra en el monte: sombrero, camisa manga larga, pantalón largo, botas de hule, bloqueador. Un pequeño recuadro tachado con chancletas, collar y zapatos de vestir. Sin marcas visibles en la ropa. Diversidad de pueblos y géneros. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"Shirt","body":"Regla general: **cómodo, seguro y apropiado al clima**. No hace falta ropa cara: basta con que cumpla su función.","reveal":[{"icon":"Shirt","front":"Ropa","back":"**Cómoda y holgada**, de tela que deje pasar el aire (como el algodón). Que no apriete ni se enrede."},{"icon":"Footprints","front":"Calzado","back":"**Tenis o zapatos deportivos** con suela que no resbale, **bien amarrados**. Nada de chancletas ni zapatos de vestir."},{"icon":"Sun","front":"Sol y calor","back":"Gorra o sombrero, **bloqueador** y ropa de colores claros. Lleva **agua**."},{"icon":"Snowflake","front":"Frío","back":"Varias **capas** (camiseta, suéter, chumpa) que te puedas quitar al entrar en calor y volver a poner al terminar."},{"icon":"TreePine","front":"Monte o siembra","back":"**Pantalón largo**, **manga larga** y zapatos cerrados o botas: te protegen de espinas, piedras e insectos."},{"icon":"Gem","front":"Sin accesorios","back":"Quítate **aretes, collares, relojes** y saca objetos de los bolsillos. Recoge el cabello largo. Evitas golpes y rasguños."}]},"id":"s06-ef-2-1"},{"fase":"construir","areas":["ef","cnt"],"cnb":["ef:3.1.2"],"ambito":"ser","title":"La respiración que calma","prompt":"Cuando haces ejercicio o sientes nervios, respiras rápido y el corazón se acelera. Puedes **ayudar a tu cuerpo a calmarse** con la respiración. Mira la animación y toca cada tarjeta.","type":"explain","props":{"icon":"Wind","body":"La respiración **abdominal lenta** usa el **diafragma**, un músculo debajo de los pulmones. Al respirar despacio y profundo, el cuerpo recibe la señal de que puede calmarse.","reveal":[{"icon":"Wind","front":"Inhala","back":"Por la **nariz**, contando **4**, inflando el **abdomen** como un globo (los hombros no suben)."},{"icon":"Hourglass","front":"Exhala","back":"Por la **boca**, despacio, contando **4 a 6**, desinflando el globo. Exhalar más largo que inhalar ayuda a calmarse."},{"icon":"Repeat","front":"Repite","back":"Haz de **5 a 10** respiraciones. Puedes hacerlo en una silla, de pie o boca arriba en el suelo."},{"icon":"Heart","front":"¿Cuándo?","back":"Después del ejercicio, antes de un partido o una prueba, cuando sientes enojo o miedo. Es tu herramienta para el **equilibrio emocional**."}]},"id":"s06-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:3.1.2"],"ambito":"ser","title":"Ejemplo resuelto: la relajación de tensión y soltura","prompt":"Otra técnica: **tensar y soltar** los músculos. Mira cómo la usa Tomás después de un partido en el que se enojó.","type":"worked-example","props":{"icon":"Smile","problem":"Tomás perdió un partido y siente los hombros duros, los puños apretados y la respiración agitada.","steps":[{"text":"Se sienta cómodo en un lugar tranquilo y hace **3 respiraciones abdominales** lentas."},{"text":"**Manos:** aprieta los puños fuerte **5 segundos**… y los **suelta 10 segundos**, notando cómo se aflojan.","why":"Al sentir la diferencia entre tensión y soltura, el cuerpo aprende a relajarse."},{"text":"**Hombros:** los sube hacia las orejas 5 segundos… y los deja caer 10 segundos."},{"text":"**Cara:** arruga la cara 5 segundos… y la afloja 10 segundos."},{"text":"Termina con 3 respiraciones más y nota cómo se siente: más tranquilo y listo para hablar de lo que pasó."}],"answer":"Tensar **5 s** y soltar **10 s** cada grupo de músculos, con respiraciones lentas al inicio y al final, ayuda a recuperar la calma.","tip":"Aprieta con fuerza, pero sin dolor. Si algo duele, no lo tenses tanto."},"id":"s06-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"conocer","prompt":"Mañana hay clase de Educación Física en la cancha, a pleno sol. ¿Qué te pondrías?","explain":"Ropa **cómoda y fresca**, **tenis bien amarrados** y **gorra**. El vestuario adecuado te protege y te deja moverte con libertad.","type":"choice","props":{"options":[{"id":"a","text":"Ropa cómoda y fresca, tenis bien amarrados y gorra","icon":"Shirt"},{"id":"b","text":"Pantalón de vestir, zapatos lustrados y reloj","icon":"Briefcase","feedback":"Esa ropa limita el movimiento y los zapatos de vestir resbalan."},{"id":"c","text":"Chancletas para ir más fresco","icon":"Footprints","feedback":"Las chancletas se salen y no protegen los pies: aumentan el riesgo de golpes y torceduras."}],"correct":["a"]},"id":"s06-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"conocer","prompt":"Clasifica cada prenda o accesorio para una clase de Educación Física en la cancha.","hint":"Piensa: ¿me deja mover?, ¿me protege?, ¿puede golpearme o hacerme caer?","explain":"Lo adecuado es cómodo, seguro y según el clima. Los accesorios y el calzado inadecuado pueden causar lesiones.","type":"sort","props":{"buckets":[{"id":"si","label":"Adecuado","icon":"Check","color":"var(--c-ok)"},{"id":"no","label":"No adecuado","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"v1","text":"Tenis bien amarrados","bucket":"si"},{"id":"v2","text":"Collar largo","bucket":"no"},{"id":"v3","text":"Camiseta de algodón holgada","bucket":"si"},{"id":"v4","text":"Chancletas","bucket":"no"},{"id":"v5","text":"Gorra y bloqueador en día de sol","bucket":"si"},{"id":"v6","text":"Pantalón de vestir ajustado","bucket":"no"}]},"id":"s06-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:3.1.2"],"ambito":"ser","prompt":"¡Mide cómo te calmas! **Parte 1:** mide tu pulso en reposo. **Parte 2:** haz 1 minuto de actividad intensa (trote en tu lugar con rodillas arriba y saltos suaves) y mide tu pulso. **Parte 3:** siéntate y haz respiración abdominal (inhala 4, exhala 6) y la relajación de tensión y soltura de manos, hombros y cara; mide otra vez. Observa cómo tu pulso baja. **Poco espacio:** todo en tu lugar. **Adaptación:** la actividad intensa puede ser con los brazos, sentado.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de la actividad intensa","exercise":{"name":"Trote con rodillas arriba y saltos suaves","icon":"Activity","seconds":60}},{"label":"Después de respirar y relajarte","exercise":{"name":"Respiración 4-6 y tensión-soltura","icon":"Wind","seconds":90}}]},"id":"s06-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:3.1.6"],"ambito":"hacer","prompt":"Como preparación para la actividad física del sábado hay una **jornada de siembra** en la montaña: habrá sol, tierra, espinas y piedras. ¿Qué vestuario es adecuado? **Elige todas las correctas.**","explain":"En el monte hay que proteger la piel y los pies: manga y pantalón largos, zapatos cerrados, sombrero y bloqueador. Las chancletas y los shorts dejan la piel expuesta a espinas e insectos.","type":"choice","props":{"multiple":true,"options":[{"id":"a","text":"Pantalón largo y camisa de manga larga"},{"id":"b","text":"Botas o zapatos cerrados"},{"id":"c","text":"Sombrero o gorra y bloqueador"},{"id":"d","text":"Chancletas y short","feedback":"Dejan los pies y las piernas expuestos a espinas, piedras e insectos."}],"correct":["a","b","c"]},"id":"s06-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:3.1.2"],"ambito":"ser","prompt":"Como recuperación emocional antes de volver a la actividad física, ¿qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Heart","text":"Faltan 5 minutos para la final del torneo de pases. **Ana** siente el corazón acelerado, las manos sudadas y dice: \\"Mejor no juego, me voy a equivocar\\"."},"options":[{"id":"a","icon":"X","text":"Decirle: \\"Si tienes miedo, mejor quédate afuera\\"","consequence":"Ana se pierde la final y se queda con la idea de que los nervios no se pueden manejar.","values":["Evitar"],"constructive":false},{"id":"b","icon":"Wind","text":"Invitarla a hacer juntas 5 respiraciones abdominales y a soltar hombros y manos","consequence":"Ana se calma un poco, siente apoyo y decide jugar. Los nervios no desaparecen del todo, pero ya no la controlan.","values":["Empatía","Autocontrol","Compañerismo"],"constructive":true},{"id":"c","icon":"MessageCircle","text":"Recordarle que equivocarse es parte de aprender y que el equipo la apoya","consequence":"Ana se siente acompañada. Con palabras de apoyo y respiración, la confianza crece.","values":["Apoyo","Respeto"],"constructive":true}]},"id":"s06-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:3.1.2"],"prompt":"Durante la recuperación de la actividad física, en la respiración abdominal lenta, ¿qué parte del cuerpo se infla al inhalar?","type":"choice","props":{"options":[{"id":"a","text":"El abdomen"},{"id":"b","text":"Los hombros, que suben hasta las orejas"},{"id":"c","text":"Las mejillas"}],"correct":["a"]},"id":"s06-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:3.1.6","ef:3.1.2"],"prompt":"Sobre preparación y recuperación para la actividad física, ¿verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Para hacer ejercicio conviene quitarse aretes, collares y relojes.","answer":true},{"text":"Con frío es mejor usar varias capas de ropa que te puedas quitar.","answer":true},{"text":"En la relajación de tensión y soltura se aprieta el músculo hasta que duela.","answer":false,"why":"Se aprieta con fuerza pero sin dolor, y luego se suelta."},{"text":"Exhalar despacio y más largo que la inhalación ayuda a calmarse.","answer":true}]},"id":"s06-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["ef"],"cnb":["ef:3.1.2"],"type":"reflection","props":{"statements":["Paso el balón con la parte interna y externa de cada pie","Elijo el vestuario adecuado para cada actividad","Uso la respiración y la relajación para calmarme"],"commitments":["Revisaré mi ropa y mis cordones antes de cada clase","Practicaré 5 respiraciones lentas antes de dormir","Usaré la respiración cuando sienta nervios o enojo"]},"id":"s06-ef-2-11"}],"kind":"materia","area":"ef","day":5}}]'),o={mission:e,lessons:a};export{o as default,a as lessons,e as mission};
